INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2009', 'spa', 'Partícula presentativa: he aquí, mira; con sufijo de 1.ª persona: heme aquí; como respuesta a un llamado: aquí estoy.', 'הִנֵּה es la gran llamada de atención de la Biblia hebrea: una partícula deíctica que sacude al oyente y le dice ''¡Mira!''. Con más de 1.000 apariciones, introduce visiones (Gn 1:29, ''he aquí, os he dado toda planta''), anuncia giros dramáticos y enmarca el discurso divino. Cuando se combina con el sufijo de primera persona (הִנְנִי), asume dos funciones fascinantemente distintas: una declaración autorreferencial que dirige la atención hacia la acción inminente del hablante (''He aquí, yo traigo el diluvio'', Gn 6:17), y la inolvidable fórmula de respuesta ''Aquí estoy'' — la respuesta de Abraham a Dios en el monte Moria (Gn 22:1), la de Samuel en la noche (1 S 3:4) y la de Isaías ofreciéndose para la misión profética (Is 6:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2011', 'spa', 'Hinom — nombre propio en el topónimo Ge-ben-Hinom (''Valle del hijo de Hinom''), al sur de Jerusalén', 'Nombre propio de etimología incierta, conocido exclusivamente como parte del topónimo compuesto ge-ben-hinom o ge-hinom — el ''Valle del (hijo de) Hinom'' — un barranco que corre a lo largo del borde sur de Jerusalén. En Josué 15:8 y 18:16 aparece como un marcador fronterizo neutral entre Judá y Benjamín. Sus asociaciones más oscuras surgen en Reyes, Crónicas y Jeremías, donde se convierte en el sitio de sacrificios infantiles a Moloc (2 R 23:10; 2 Cr 28:3; 33:6; Jer 7:31-32; 19:2, 6; 32:35). Jeremías profetiza su cambio de nombre como el ''Valle de la Matanza''. Este topónimo dio origen más tarde al griego Gehenna, el término neotestamentario para el juicio escatológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2012', 'spa', 'Hena (toponimo; ubicacion desconocida)', 'Nombre de una ciudad mencionada en las jactancias asirias de conquista, enumerada junto a Sefarvaim e Iva (2 Re 18:34; 19:13; Is 37:13). El rey asirio desafia: ''Donde estan los dioses de Hamat y de Arfad? Donde estan los dioses de Sefarvaim, de Hena y de Iva?'' Su ubicacion exacta se desconoce, aunque los estudiosos sugieren un sitio en Siria o Mesopotamia. Las traducciones conservan el nombre (Hena, Hena) sin intentar identificar ni traducir el toponimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2013', 'spa', '¡Silencio! ¡Calla! — interjección onomatopéyica que ordena callar, especialmente ante YHWH; rara vez como verbo causativo, hacer callar.', 'La interjección הַס es una orden brusca y onomatopéyica que significa «¡Silencio!» o «¡Calla!». Transmite una urgencia que va más allá de una petición cortés: cuando Ehud dice הָס a los sirvientes del rey Eglón (Jue 3:19), está despejando la sala para un encargo secreto y mortal. La palabra alcanza su registro más solemne en los profetas, donde exige silencio reverente ante YHWH: «Calla en la presencia del Señor DIOS» (Sof 1:7; Hab 2:20; Zac 2:17). De modo singular, puede conjugarse como verbo: Caleb «hizo callar» al pueblo delante de Moisés (Nm 13:30), mostrando la capacidad del hebreo para verbalizar incluso sus interjecciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2015', 'spa', 'Voltear, derribar, trastornar o transformar; abarca la inversión física, la destrucción divina y el cambio interior de estado.', 'Voltear, derribar, trastornar o transformar; abarca la inversión física, la destrucción divina y el cambio interior de estado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2022', 'spa', 'Monte, montaña, cerro o región montañosa; una cumbre singular, una cordillera o un distrito de tierras altas habitado.', 'Uno de los sustantivos más frecuentes de la Biblia hebrea, har designa cualquier masa terrestre elevada, desde un pico solitario hasta un territorio entero de tierras altas. Cuando la Escritura dice que Moisés subió ''al monte'' (Éx 19:3), la palabra evoca una cumbre singular y sobrecogedora donde el cielo toca la tierra. En su forma plural abarca paisajes completos, como cuando el salmista declara que los montes tiemblan (Sal 46:2). Sin embargo, har también nombra regiones habitadas: ''la montaña de Efraín'' no es una sola cumbre sino un distrito ondulado de tierras altas, uso confirmado por glosas en lenguas romances como ''monte de'' que subrayan el sentido territorial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2023', 'spa', 'Hor — montaña en la frontera de Edom donde Aarón murió y fue sepultado', 'Hor — montaña en la frontera de Edom donde Aarón murió y fue sepultado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2026', 'spa', 'Matar o dar muerte violentamente; como participio, el matador o los muertos; en voces pasivas, ser muerto.', 'El verbo hebreo primario para la muerte violenta y deliberada, más amplio que ratsaj (que tiende al asesinato) y más visceral que mut (que puede significar simplemente ''morir''). Harag domina las narraciones bélicas: los israelitas mataron a los cananeos, Finees mató a los idólatras, Jehú mató a la casa de Acab. Pero también aparece en contextos intensamente personales: el temor de Caín a que cualquiera lo mate (Gn 4:14), el juramento de Esaú de matar a Jacob (Gn 27:42) y la terrible masacre de Siquem (Gn 34:26). El alemán erschlagen (''matar a golpes'') y el español matar/mataron lo traducen con precisión. El uso del cognado en la estela de Mesha confirma su antigüedad en todo el semítico noroccidental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2027', 'spa', 'matanza, carnicería; acto de matar violentamente, especialmente en batalla o juicio divino', 'Sustantivo masculino que designa matanza o muerte violenta, empleado en contextos de guerra y juicio divino. En Ester 9:5 describe la matanza que los judíos hicieron de sus enemigos, junto con la destrucción (אָבְדָן). Proverbios 24:11 exhorta a rescatar a quienes son arrastrados hacia la matanza, mientras que Isaías 30:25 vislumbra un catastrófico ''día de gran matanza'' que acompañará la intervención futura de Dios. El término transmite siempre un sentido de violencia deliberada y a gran escala, con connotaciones de gravedad y finalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2028', 'spa', 'matanza, mortandad; usada en expresiones proféticas de juicio y destrucción', 'Sustantivo femenino que designa matanza, y que aparece exclusivamente en expresiones proféticas y simbólicas. Jeremías renombra el Valle de Ben-Hinom como el ''Valle de la Matanza'' (גֵּיא הַהֲרֵגָה, Jer 7:32; 19:6), transformando un sitio de sacrificio infantil en emblema de la retribución divina. Jeremías 12:3 habla de un ''día de matanza'' para los impíos, mientras que Zacarías 11:4, 7 describe a Israel y Judá como ''ovejas de matanza'', explotadas por pastores negligentes. El término funciona siempre como símbolo profético de juicio masivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2029', 'spa', 'Concebir, quedar encinta; como participio, la que concibió; en voz pasiva, ser concebido', 'Concebir, quedar encinta; como participio, la que concibió; en voz pasiva, ser concebido');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2030a', 'spa', 'Embarazada, encinta — adjetivo femenino que describe a una mujer que ha concebido, usado predicativa y atributivamente', 'Adjetivo femenino que significa ''embarazada'' o ''encinta'', usado tanto predicativa como atributivamente en la Biblia hebrea. Aparece en algunos de los anuncios más trascendentales de la Escritura: la declaración del ángel a Agar, ''estás encinta y darás a luz un hijo'' (Gn 16:11), repetida en la anunciación a la madre de Sansón (Jue 13:5, 7) y en la profecía del Emmanuel de Isaías (Is 7:14). En contextos más sombríos, describe a mujeres embarazadas despedazadas en la guerra (2 R 8:12; 15:16; Am 1:13). Jeremías maldice el vientre que estuvo ''siempre encinta'' de él (Jer 20:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2032', 'spa', 'concepción, embarazo; el acto o estado de concebir un hijo', 'Sustantivo que designa el acto o el estado de concebir descendencia. Dios le dice a Eva: «Multiplicaré en gran manera tu dolor en la concepción; con dolor darás a luz hijos» (Gn 3:16), donde el término aparece en paralelo con el alumbramiento. El Señor «le concedió concebir» a Rut, y ella dio a luz un hijo (Rt 4:13). Oseas lamenta la pérdida de bendición para Israel «desde el nacimiento, desde el vientre, desde la concepción» (Os 9:11). El campo semántico abarca tanto el momento inicial como el estado resultante del embarazo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2039', 'spa', 'Harán; nombre personal que significa ''montañés,'' llevado por el hermano de Abram (padre de Lot) y un levita.', 'Nombre personal que probablemente significa ''montañés'' o ''habitante de la montaña.'' El portador más destacado es el hijo de Taré y hermano de Abram, quien engendró a Lot, Milca e Isca antes de morir en Ur de los Caldeos (Gn 11:27-31). Su muerte prematura pone en marcha la vinculación de Lot con la casa de Abram, un hilo narrativo que se extiende a lo largo de Génesis. Un segundo Harán aparece como levita gersonita en el registro administrativo de David (1 Cr 23:9). Nótese que este nombre personal (Harán con hé) es distinto del topónimo Harrán (con jet), la posterior escala de Abram.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2040', 'spa', 'Derribar, demoler o irrumpir; se usa para destruir muros, altares y ciudades, y para traspasar límites', 'Derribar, demoler o irrumpir; se usa para destruir muros, altares y ciudades, y para traspasar límites');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2042', 'spa', 'harar — montaña o cerro; una elevación geográfica, usada en contextos poéticos y especiales', 'harar — montaña o cerro; una elevación geográfica, usada en contextos poéticos y especiales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2043', 'spa', 'Hararita; gentilicio que designa a ciertos guerreros valientes de David', 'Adjetivo gentilicio que significa ''el hararita'', posiblemente indicando a un habitante de la montaña o a alguien procedente de una localidad desconocida. Aparece exclusivamente en las listas de los guerreros de elite de David. Sama hijo de Agee el hararita (2 Sam 23:11, 33) y Ahiam hijo de Sarar el hararita (2 Sam 23:33; 1 Cr 11:35) son los dos heroes identificados con este gentilicio. La Septuaginta lo traduce de maneras variadas, lo que sugiere que el origen del nombre ya era oscuro en la antiguedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2047', 'spa', 'Hatac, oficial de la corte persa que sirvio de intermediario entre Ester y Mardoqueo.', 'Nombre propio de origen persa antiguo que designa a un oficial (o eunuco) de la corte del rey Asuero, asignado al servicio de la reina Ester. Hatac desempeno un papel crucial durante la crisis provocada por el decreto genocida de Aman, llevando y trayendo mensajes entre Ester, recluida en el palacio, y Mardoqueo, apostado junto a la puerta (Est 4:5-10). Su funcion como intermediario fue indispensable, ya que Ester no podia salir del palacio y Mardoqueo no podia entrar. El nombre se conserva con minima variacion en las distintas tradiciones de traduccion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2048b', 'spa', 'Burlarse, escarnecer o engañar; Hifil: tratar con desprecio mediante burla o falsedad; Hofal: ser engañado.', 'Verbo de engaño interpersonal que oscila entre la burla despectiva y el fraude deliberado. En el ciclo de Sansón, Dalila reprocha repetidamente: «te has burlado de mí» (Jue 16:10, 13, 15). Pero la misma forma Hifil describe el engaño económico de Labán contra Jacob, cambiándole el salario diez veces (Gn 31:7), y las dilaciones de Faraón con Moisés (Éx 8:29). Job 13:9 pregunta si acaso se puede «engañar a Dios como se engaña a un mortal». El único Hofal, en Isaías 44:20, diagnostica la autoilusión del idólatra: «un corazón engañado lo ha desviado». La raíz posiblemente se relaciona con el árabe dalla («coquetear»), sugiriendo un origen en manipulación juguetona que degeneró en fraude.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2053', 'spa', 'Ganchos o clavijas de oro y plata fijados a los postes del tabernáculo para colgar cortinas y velos', 'Presente exclusivamente en las instrucciones detalladas de la fuente Sacerdotal para el tabernáculo, este sustantivo se refiere a los pequeños ganchos o clavijas metálicas fijados a los pilares de madera de los cuales se suspendían los cortinajes sagrados. Todas las apariciones se concentran en Éxodo 26-27 y 36-38, siempre en plural. La traducción uniforme en diversos idiomas — español ''ganchos'', francés ''crochets'', alemán ''Haken'' — confirma un referente único y concreto: la ferretería funcional que sostenía las cortinas del santuario, vinculando la precisión arquitectónica con la santidad litúrgica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2060', 'spa', 'Vasti — la reina persa destituida por Asuero (Jerjes) por negarse a comparecer en su banquete.', 'Vasti — la reina persa destituida por Asuero (Jerjes) por negarse a comparecer en su banquete.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2061', 'spa', 'Lobo; cánido depredador usado literal y figuradamente para personas violentas, rapaces o enemigos.', 'La palabra hebrea común para el lobo (Canis lupus), un feroz depredador bien conocido en el antiguo Cercano Oriente. Nunca aparece en descripciones narrativas de animales reales, sino siempre en profecía, poesía o símil. Benjamín es un «lobo rapaz» (Gn 49:27), y los jueces de Jerusalén son «lobos nocturnos» (Sof 3:3). De modo notable, la visión mesiánica de Isaías presenta al lobo morando con el cordero (Is 11:6) y alimentándose junto a él (Is 65:25), imágenes de una paz radical. Cognado con el árabe dhi''b, el arameo deba y el etiópico zi''b, el término refleja una conciencia semítica ampliamente compartida de este depredador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2062', 'spa', 'Zeeb; príncipe madianita capturado y ejecutado por los efraimitas durante la campaña de Gedeón. Su nombre significa ''lobo''.', 'Nombre propio de un príncipe madianita muerto junto con Oreb durante la persecución del ejército madianita por parte de Gedeón. El nombre significa ''lobo'', acorde con la reputación depredadora de los incursores madianitas que habían devastado las cosechas de Israel. Jueces 7:25 relata que los efraimitas capturaron a Zeeb en un lagar que desde entonces se llamó «el lagar de Zeeb» (yeqev-ze''ev). Salmo 83:12 rememora esta victoria como paradigma de la liberación divina. El nombre se transliterá de manera uniforme en las diversas tradiciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2063', 'spa', 'Esta (pronombre demostrativo fem.); también en locuciones preposicionales: como esto, en esto, a esto, y esto.', 'Contrapartida femenina del demostrativo hebreo común zeh, zo''t señala a una persona, cosa o situación específica que está presente o ha sido mencionada recientemente. Con más de 500 apariciones, es uno de los vocablos más funcionales del discurso hebreo; sin embargo, su significado cambia notablemente al combinarse con preposiciones: ke- produce ''como esto, así'', be- produce ''con esto, en esto'', y lamed produce ''a esto, para esto''. Estos compuestos preposicionales se convierten en modismos fijos de manera, instrumento y propósito, otorgando a un solo pronombre un alcance retórico sorprendente a través de textos narrativos, legales y poéticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2066', 'spa', 'Zabad: nombre propio masculino que significa «él ha dado» o «don», llevado por al menos siete hombres en el Antiguo Testamento.', 'Zabad es un nombre propio hebreo que significa «él ha dado» o «don», emparentado con la raíz verbal común z-b-d. Lo llevan varios individuos distintos: un descendiente de Judá por la línea de Sesán (1 Cr 2:36-37), un efrateo muerto en una incursión por ganado (1 Cr 7:21), uno de los guerreros de élite de David (1 Cr 11:41), un conspirador que asesinó al rey Joás de Judá (2 Cr 24:26, llamado Jozacar en 2 R 12:21) y tres exiliados que regresaron y se habían casado con mujeres extranjeras (Esd 10:27, 33, 43). La frecuencia del nombre entre los israelitas del período posexílico puede reflejar su resonancia teofórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2067', 'spa', 'Zabdi; nombre propio de varios israelitas, que posiblemente significa ''mi regalo'' o ''regalo de Yah''.', 'Nombre propio masculino que probablemente significa ''mi regalo'' o quizá sea una forma abreviada de Zabdiel (''regalo de Dios''). Lo llevan al menos cuatro personas distintas en la Biblia hebrea: el abuelo de Acán, de la tribu de Judá (Jos 7:1, 17-18); un benjaminita mencionado en la genealogía de 1 Crónicas 8:19; un encargado de las bodegas de vino de David (1 Cr 27:27); y un levita en Nehemías 11:17, posiblemente identificable con Zicri. El cognado árabe zabd (''regalo'') respalda la interpretación etimológica. El nombre aparece en el Nuevo Testamento como Zebedeo (griego Ζεβεδαῖος).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2069', 'spa', 'Zebadías: nombre masculino que significa «YHWH ha otorgado», llevado por al menos nueve hombres en la Biblia hebrea.', 'Zebadías (también en su forma teofórica larga Zevadyahu) significa «YHWH ha otorgado» o «don del SEÑOR», compartiendo raíz con nombres como Josabad. Lo llevan al menos nueve individuos distintos en Crónicas y Esdras, entre ellos benjaminitas (1 Cr 8:15, 17), uno de los guerreros de David que desertaron de Saúl (1 Cr 12:7), un portero levita (1 Cr 26:2), un oficial militar (1 Cr 27:7), el juez principal de Josafat para asuntos reales (2 Cr 19:11) y un exiliado que regresó (Esd 8:8). La frecuencia del nombre refleja la gratitud de Israel por la provisión divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2073', 'spa', 'Morada excelsa, habitación elevada; residencia celestial o sublime, especialmente de Dios', 'Sustantivo poético que significa ''morada excelsa'' o ''habitación elevada'', reservado para contextos teológicos solemnes. Salomón declara el templo un בֵּית זְבֻל, una ''casa de morada sublime'' para el SEÑOR (1 Re 8:13; 2 Cr 6:2). Isaías 63:15 lo empareja con ''cielo'' como la alta morada de la santidad de Dios. En Habacuc 3:11, incluso el sol y la luna tienen su זְבֻלָה, su estación celestial. El cognado acadio bīt zabal (''casa elevada'') confirma esta resonancia arquitectónico-cósmica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2074', 'spa', 'Zabulón — el sexto hijo de Jacob y Lea; la tribu israelita y su territorio en la región de Galilea', 'Zabulón — el sexto hijo de Jacob y Lea; la tribu israelita y su territorio en la región de Galilea');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2075', 'spa', 'zabulonita; gentilicio que identifica a miembros de la tribu de Zabulón', 'Adjetivo gentilicio que identifica a los miembros de la tribu de Zabulón. Aparece como «el zabulonita» para designar al juez Elón (Jue 12:11-12) y de forma colectiva en el censo de «los zabulonitas» (Nm 26:27). Se trata de la morfología gentilicia estándar del hebreo: un nombre propio transformado en adjetivo o sustantivo colectivo que identifica a los descendientes o miembros de un grupo tribal. Zabulón fue el décimo hijo de Jacob.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2076', 'spa', 'Degollar para el sacrificio; ofrecer sacrificio cultual', 'Este verbo hebreo describe ante todo el acto del sacrificio ritual en la vida cultual de Israel. La palabra abarca tanto la matanza física del animal como la ofrenda religiosa en sí. El tronco Qal suele denotar ofrecer sacrificio a Dios (aunque a veces a los ídolos), mientras que la forma intensiva Piel describe una actividad sacrificial habitual o persistente. En ciertos contextos, particularmente narrativos, el verbo puede referirse simplemente a la matanza de un animal para alimento, si bien el sentido sacrificial permanece como el primario a lo largo de toda la Escritura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2077', 'spa', 'Sacrificio, ofrenda animal degollada en el culto; la ofrenda cultual más común y antigua de Israel.', 'El término sacrificial fundamental de la Biblia hebrea, que designa un animal degollado como ofrenda comunitaria cuya carne se compartía en una comida sagrada. A diferencia del holocausto (עֹלָה) y de la ofrenda de cereal (מִנְחָה), el זֶבַח era el banquete compartido originario entre los adoradores y Dios: Dios recibía la sangre y la grasa, el pueblo comía la carne. Desde el sacrificio de Jacob en Mizpa (Gn 31:54) hasta las ofrendas de paz del Levítico, esta palabra recorre toda la vida cultual de Israel. El alemán Schlachtopfer (''ofrenda de matanza'') conserva de manera única la conexión etimológica con la acción de degollar que el español ''sacrificio'' oscurece.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2078', 'spa', 'Zébaj — rey madianita capturado y ejecutado por Gedeón junto con Zalmuna.', 'Zébaj — rey madianita capturado y ejecutado por Gedeón junto con Zalmuna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2083', 'spa', 'Zebul; oficial y gobernador de Siquem bajo Abimelec, activo en la narrativa de la revuelta de Gaal.', 'Nombre propio de un hombre que sirvió como gobernador o prefecto de la ciudad de Siquem bajo Abimelec, hijo de Gedeón. Zebul aparece exclusivamente en Jueces 9, donde desempeña un papel crucial en el conflicto entre Abimelec y el rebelde Gaal hijo de Ebed. Cuando Gaal fomenta el descontento durante un banquete, Zebul envía aviso secreto a Abimelec y luego se burla de la vacilación de Gaal ante la cercanía del contraataque. Su nombre puede estar relacionado con el sustantivo zebul, que significa ''morada exaltada'' o ''lugar elevado''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2086', 'spa', 'Insolente, arrogante, presuntuoso — siempre referido a quienes desafían a Dios y sus mandamientos', 'Adjetivo que funciona casi como un término técnico para el obstinadamente rebelde. Solo en el Salmo 119 aparece siete veces, designando consistentemente a quienes desprecian la Torá y se burlan de los fieles. El זֵד no es meramente orgulloso sino presuntuosamente rebelde — Proverbios 21:24 lo vincula con ''burlador'' y ''altivo''. Malaquías e Isaías extienden la acusación a comunidades enteras cuya arrogancia provoca el juicio divino. El español ''soberbio'' y el alemán ''Freche'' captan la insolencia agresiva que implica el término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2087', 'spa', 'Soberbia, arrogancia — orgullo insolente que desafía la autoridad, sea humana o divina.', 'Soberbia, arrogancia — orgullo insolente que desafía la autoridad, sea humana o divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2088', 'spa', 'Este, esto (pronombre demostrativo); con preposiciones: de aquí, en esto, así/como esto.', 'זֶה es el pronombre demostrativo de cercanía masculino básico del hebreo bíblico — ''este'', ''esto'' — y en su forma simple señala algo inmediatamente presente en el contexto del hablante o del discurso. Lo que hace especialmente interesante a este lema es cómo el sistema aglutinante de preposiciones del hebreo genera toda una familia de sentidos derivados: מִזֶּה se convierte en ''de aquí'' o ''de este lado'', בָּזֶה en ''en esto'' o ''aquí'', y כָּזֶה en ''como esto'' o ''así''. Cada una de estas combinaciones preposicionales ha desarrollado suficiente independencia semántica como para que los traductores recurran a vocabulario distinto. El elemento demostrativo cognado z- recorre toda la familia semítica, lo que convierte a este en uno de los morfemas gramaticales más antiguos y estables de la lengua humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2089', 'spa', 'uno del rebaño; oveja o cabra individual, miembro de un rebaño colectivo', 'Este sustantivo singular designa un animal individual del rebaño, ya sea oveja o cabra, distinguiendo miembros particulares del término colectivo «rebaño». Los textos legales y rituales lo emplean al especificar animales individuales para sacrificio, compensación o leyes de propiedad. La palabra enfatiza la identidad individual dentro del conjunto: una oveja entre muchas. Las leyes de Deuteronomio sobre ayudar al animal extraviado de un vecino, el relato de Samuel sobre tomar la única cordera de un pobre y las regulaciones de Éxodo sobre el robo emplean este término. Nunca aparece en plural, ya que el sustantivo colectivo cumple esa función.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2090', 'spa', 'Esta (pronombre demostrativo femenino); con la preposición ke-, ''así, de esta manera''.', 'Esta (pronombre demostrativo femenino); con la preposición ke-, ''así, de esta manera''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2091', 'spa', 'Oro; el metal precioso, ya sea mineral en bruto, material refinado, moneda o patrón figurado de valor.', 'Zahav es la palabra hebrea estándar para el oro en todas sus formas y funciones. Casi 390 apariciones abarcan desde el mineral en bruto de Havilá (Gn 2:11-12), el metal refinado para los utensilios del Tabernáculo (Éx 25:11), la riqueza regia como el legendario oro de Ofir de Salomón (1 R 9:28), hasta la imaginería figurada donde el oro representa la pureza probada por el fuego (Job 23:10; Zac 13:9). Sus cognados se extienden por todas las ramas del semítico: árabe ذهب, arameo דהב, sabeo dhb. Las traducciones son notablemente uniformes: español oro, francés or, alemán Gold, reflejo del reconocimiento cultural universal de este metal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2094b', 'spa', 'Advertir, amonestar, prevenir (Hifil activo); recibir advertencia, ser amonestado (Nifal reflexivo-pasivo)', 'Advertir, amonestar, prevenir (Hifil activo); recibir advertencia, ser amonestado (Nifal reflexivo-pasivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2098', 'spa', 'Este; que, quien — pronombre poético arcaico que funciona como demostrativo y relativo', 'Pronombre arcaico indeclinable que se encuentra casi exclusivamente en la poesía, especialmente en los Salmos y el Cántico del Mar (Éx 15). Como demostrativo significa ''este'' (Hab 1:11 ''esta su fuerza''; Sal 62:11 ''estas dos cosas he oído''). Como pronombre relativo equivale al más común אֲשֶׁר, introduciendo cláusulas como ''el pueblo que redimiste'' (Éx 15:13, 16) y ''contra quien pecamos'' (Is 42:24). Su registro elevado y solemne confiere a los pasajes una solemnidad arcaica que el hebreo posterior reservó para contextos litúrgicos y proféticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2100', 'spa', 'Fluir o manar; se usa para agua, una tierra que fluye leche y miel, flujos corporales en la ley de pureza, y figuradamente para consumirse', 'Fluir o manar; se usa para agua, una tierra que fluye leche y miel, flujos corporales en la ley de pureza, y figuradamente para consumirse');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2101', 'spa', 'Flujo o descarga corporal de los genitales que produce impureza ritual según la ley levítica', 'Término técnico confinado enteramente a Levítico 15, donde rige la legislación de pureza ritual relativa a las emisiones genitales. Se aplica tanto a hombres como a mujeres, abarcando descargas anormales que hacen a una persona ceremonialmente impura, y describe los pasos hacia la purificación. La palabra no aparece en ningún otro lugar de la Biblia hebrea, lo que subraya su registro legal especializado. La evidencia interlingüística — francés ''écoulement'', alemán ''Ausfluss'', español ''flujo'' — apunta uniformemente a una descarga médica fluida más que a una función corporal general.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2102', 'spa', 'Actuar con soberbia, ser arrogante en desafío a Dios o la autoridad; también como raíz homónima, hervir o cocer.', 'Actuar con soberbia, ser arrogante en desafío a Dios o la autoridad; también como raíz homónima, hervir o cocer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2108', 'spa', 'Excepto, aparte de, fuera de — preposición que expresa exclusión o única excepción.', 'Excepto, aparte de, fuera de — preposición que expresa exclusión o única excepción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2109b', 'spa', 'adjetivo de significado incierto; posiblemente ''bien alimentado'' o ''lujurioso'', variante textual', 'Esta rara forma participial aparece en la condena de Jeremías contra la corrupción moral de Judá, describiendo un comportamiento lujurioso. El significado exacto sigue en disputa: algunos lo relacionan con estar bien alimentado o lustroso como caballos mimados, otros con pesar o estar equipado, y otros con disposición sexual. El contexto involucra claramente una metáfora sexual, comparando la idolatría de Judá con caballos en celo. Las versiones antiguas tuvieron dificultades con la palabra, lo que sugiere que su significado era incierto desde temprano. La vívida imaginería del pasaje sobre la corrupción moral supera el valor léxico preciso de este difícil término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2111', 'spa', 'temblar, estremecerse (por miedo o sacudida física); sacudir violentamente', 'Verbo que expresa temblor, ya sea por miedo, reverencia o agitación física. Amán «tembló» ante Ester (Est 5:9), los «guardas de la casa» (las manos o los brazos) «tiemblan» en la vejez (Ecl 12:3), y Habacuc contempla a los acreedores que «sacudirán» a Babilonia con violencia (Hab 2:7). El rango semántico abarca desde el temblor involuntario provocado por el temor hasta la sacudida violenta infligida por otros, pudiendo funcionar como verbo pasivo (temblar de miedo) o causativo (sacudir con fuerza).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2112', 'spa', 'Temblar, estremecerse de pavor; verbo arameo que describe el terror ante el poder soberano.', 'Verbo arameo que aparece en las narrativas cortesanas de Daniel para describir el temblor de pavor que los pueblos experimentaban ante Nabucodonosor y ante el Dios viviente. La forma participial expresa un estado continuo de estremecimiento, no un susto momentaneo. En Dan 5:19, las naciones temblaban ante el poder absoluto del rey; en Dan 6:26, el mismo verbo se transfiere a Dios como aquel ante quien toda la tierra debe temblar. El vocablo capta la dimension visceral y fisica de esta respuesta de temor reverente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2113', 'spa', 'Temblor, horror; objeto de terror o espanto, usado en fórmulas de maldición pactual para naciones entregadas al juicio.', 'Sustantivo femenino que designa temblor o estremecimiento y, por metonimia, aquello que provoca dicho horror: un objeto de espanto. Aparece casi exclusivamente en fórmulas de maldición donde Dios amenaza con convertir a Israel o a Jerusalén en motivo de terror para las naciones. Deuteronomio 28:25 establece el patrón: ''serás objeto de זְוָעָה para todos los reinos de la tierra''. Jeremías repite esta fórmula cuatro veces (15:4; 24:9; 29:18; 34:17), combinándola con términos de vergüenza, oprobio y maldición. La palabra presenta dos variantes ortográficas —זְוָעָה y זַעֲוָה— que son formas metatéticas entre sí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2114a', 'spa', 'Ser extraño o ajeno; como participio: un extraño, forastero, extranjero o intruso, alguien que no pertenece a la familia, la comunidad o el pacto.', 'Ser extraño o ajeno; como participio: un extraño, forastero, extranjero o intruso, alguien que no pertenece a la familia, la comunidad o el pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2115', 'spa', 'exprimir, apretar, estrujar (extraer líquido de algo); aplastar', 'Verbo que denota la presión ejercida para extraer líquido o aplastar algo bajo los pies. Gedeón «exprimió» un vellón y escurrió el rocío (Jue 6:38), los huevos de avestruz pueden ser «aplastados» por las pisadas (Job 39:15), y un huevo de víbora al ser «apretado» libera su peligro (Is 59:5). La herida de Isaías 1:6 «no ha sido exprimida», es decir, no fue drenada ni tratada. El núcleo semántico gira en torno a la manipulación forzada de materia sólida o semisólida mediante compresión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2122', 'spa', 'Brillo, esplendor; específicamente la radiancia del rostro o semblante, usado exclusivamente en las secciones arameas de Daniel.', 'Sustantivo masculino arameo que significa brillo o esplendor, presente únicamente en el libro de Daniel. Describe la apariencia deslumbrante de la estatua del sueño de Nabucodonosor (Dan 2:31), la restauración del esplendor real tras su humillación (Dan 4:36) y, de manera muy vívida, la mudanza de semblante que experimenta Belsasar al ver la escritura en la pared (Dan 5:6, 9, 10). El término podría ser un préstamo del acadio zīmu (''rostro, semblante''). En español se traduce como ''semblante'' y ''esplendor'', captando tanto el aspecto facial como el luminoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2128', 'spa', 'Zif — nombre propio de localidades en Judá (una cerca de Hebrón, otra en el Néguev) y nombre personal en Crónicas.', 'Zif — nombre propio de localidades en Judá (una cerca de Hebrón, otra en el Néguev) y nombre personal en Crónicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2130', 'spa', 'zifeos; habitantes de Zif que dos veces delataron a David ante Saúl', 'Gentilicio que designa a los habitantes de Zif, una ciudad en la serranía de Judá. Son recordados principalmente por su doble traición a David, al revelar su escondite al rey Saúl en dos ocasiones distintas. El título del Salmo 54 perpetúa la memoria de su deslealtad. El término funciona como designación gentilicia estándar, identificando a las personas por su lugar de origen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2131a', 'spa', 'Proyectil, chispa, tizón ardiente; objeto ígneo que salta o vuela con fuerza destructiva', 'Sustantivo que designa proyectiles de fuego o chispas: cosas que saltan o vuelan con violencia. Describe las «teas y flechas» lanzadas en broma mortal (Prov 26:18), y a quienes encienden fuego y se ciñen de tizones ardientes (Isa 50:11, dos veces). La raíz sugiere algo que brota o se lanza: misiles ígneos, chispas o antorchas. Es fuego convertido en arma: impredecible, peligroso y destructor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2131b', 'spa', 'Grillos, cadenas; ataduras para sujetar cautivos, tanto en sentido literal como figurado de disciplina divina.', 'Sustantivo masculino que solo aparece en plural, designando los grillos o cadenas de hierro empleados para atar a los cautivos. El termino aparece en escenas vividas de cautiverio: los nobles de Ninive llevados en cadenas (Nah 3:10), pueblos sometidos que desfilan encadenados (Isa 45:14) y reyes aprisionados con grillos (Sal 149:8). Job 36:8 extiende la imagen al plano figurado: quienes estan ''atados con grillos'' de afliccion reciben la disciplina de Dios. La palabra conserva la fuerza concreta y fisica de la imagen del encadenamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2132', 'spa', 'Olivo, aceituna; también usado en el topónimo ''Monte de los Olivos''', 'Olivo, aceituna; también usado en el topónimo ''Monte de los Olivos''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2134', 'spa', 'Puro, limpio, claro — libre de contaminación; referido al aceite de oliva, incienso, cielo o carácter moral.', 'Puro, limpio, claro — libre de contaminación; referido al aceite de oliva, incienso, cielo o carácter moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2135', 'spa', 'Ser puro, purificar o purificarse; limpieza moral y ritual en las formas Qal, Piel y Hitpael.', 'Verbo de pureza moral y ritual cuyo sentido varía según la conjugación. En Qal plantea la pregunta penetrante: ''¿Puede un mortal ser puro ante Dios?'' (Job 15:14; 25:4), expresando un estado, no una acción. En Piel se vuelve activo: ''¿Cómo puede un joven mantener puro su camino?'' (Sal 119:9), y el lamento angustiado ''en vano he mantenido puro mi corazón'' (Sal 73:13). El único Hitpael, en Isaías 1:16, ordena la autopurificación: ''¡Purificaos!'' El cognado arameo deka y el árabe dhaka (''ser brillante, penetrante'') sugieren un sentido sensorial originario —la claridad ardiente de un fuego limpio— que en hebreo se convirtió en pureza moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2138', 'spa', 'Varones (colectivo); sinonimo de zakhar usado para los varones obligados a las fiestas de peregrinacion de Israel.', 'Forma variante del mas comun זָכָר (''varon''), que solo aparece con sufijos posesivos y en contextos legales y culticos. Tres de sus apariciones especifican que ''todos tus varones'' deben presentarse ante el Senor en las tres fiestas anuales de peregrinacion (Ex 23:17; 34:23; Dt 16:16). La cuarta, en las leyes de guerra (Dt 20:13), ordena dar muerte a ''todos sus varones'' cuando una ciudad rechaza las condiciones de paz. Las formas con sufijo posesivo son distintivas de este termino, diferenciandolo del mas frecuente זָכָר.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2139', 'spa', 'Zacur / Zakur — nombre personal hebreo (''recordado''), portado por varios hombres de las tribus de Rubén, Simeón y Leví.', 'Zacur / Zakur — nombre personal hebreo (''recordado''), portado por varios hombres de las tribus de Rubén, Simeón y Leví.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2140', 'spa', 'Zacai (nombre propio; posiblemente forma abreviada de Zacarías)', 'Nombre propio que aparece en las listas postexílicas de los que regresaron a Judá: cabeza de familia en Esdras 2:9 y Nehemías 7:14, y posiblemente la misma persona en Nehemías 3:20, aunque la versión griega sugiere variantes textuales. BDB propone que Zacai es una forma abreviada de Zacarías. Las traducciones conservan el nombre con ligeras variaciones. Aparece en contextos genealógicos y censales, identificando un linaje familiar entre los exiliados que retornaron.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2141', 'spa', 'Ser brillante, limpio, puro; describe resplandor fisico o pureza moral, con sentido causativo ''limpiar''.', 'Verbo que aparece unicamente en Job y Lamentaciones, abarcando desde el brillo fisico hasta la pureza moral. En Lam 4:7 describe como los nobles de Jerusalen eran antes ''mas resplandecientes que la nieve'', imagen impactante de salud y esplendor. En los argumentos teologicos de Job, cuestiona si incluso los cielos son ''puros'' ante los ojos de Dios (Job 15:15; 25:5), cuanto menos los mortales. El Hifil en Job 9:30 expresa la futilidad de la autopurificacion: ''aunque lave mis manos con lejia''. La raiz une luminosidad y limpieza moral en un mismo campo semantico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2142', 'spa', 'Recordar, acordarse; ser recordado (Nifal); hacer recordar, mencionar, invocar, proclamar (Hifil); el cronista (ptcp. Hifil).', 'Verbo fundamental de la teología pactual, זָכַר abarca desde el recuerdo íntimo hasta la proclamación pública. Cuando Dios ''recuerda'' a Noé (Gn 8:1) o su pacto (Éx 2:24), el hebreo no implica mera evocación mental sino intervención activa —una verdad que la Septuaginta capta con μιμνῄσκομαι y sus derivados. En el Hifil causativo, la palabra pasa de la memoria interior a la palabra pronunciada: invocar el nombre de Dios (Sal 20:7), mencionar dioses ajenos (Jos 23:7), o ejercer el cargo palaciego de ''cronista'' (הַמַּזְכִּיר), el funcionario que velaba por que los hechos del rey no cayeran en el olvido (2 S 8:16). El árabe ذَكَرَ, cuyo derivado ذِكْر (remembranza), resuena profundamente en la práctica religiosa semítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2143', 'spa', 'Recuerdo, memoria; un memorial o signo conmemorativo; renombre o fama', 'Recuerdo, memoria; un memorial o signo conmemorativo; renombre o fama');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2145', 'spa', 'Varón — un ser humano de sexo masculino o un animal macho, usado en contextos de creación, ley, censo, genealogía y ofrenda sacrificial.', 'Varón — un ser humano de sexo masculino o un animal macho, usado en contextos de creación, ley, censo, genealogía y ofrenda sacrificial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2146', 'spa', 'Memorial, recordatorio; un signo conmemorativo, señal o registro destinado a preservar la memoria ante Dios o entre las personas', 'Memorial, recordatorio; un signo conmemorativo, señal o registro destinado a preservar la memoria ante Dios o entre las personas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2147', 'spa', 'Zicri — nombre propio portado por múltiples individuos a lo largo de la Biblia hebrea.', 'Zicri — nombre propio portado por múltiples individuos a lo largo de la Biblia hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2148a', 'spa', 'Zacarías — nombre propio que significa ''Yah ha recordado'', portado por más de una docena de individuos en la Biblia hebrea', 'Zacarías — nombre propio que significa ''Yah ha recordado'', portado por más de una docena de individuos en la Biblia hebrea');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2151b', 'spa', 'Ser glotón o persona despreciable; derrochar, ser pródigo; ser vil o insignificante.', 'Verbo que aparece únicamente como participio Qal, con dos significados relacionados pero distinguibles. En su sentido moral, describe a un glotón o derrochador: alguien que consume de manera desenfrenada y sin mesura. Deuteronomio 21:20 lo empareja con ''borracho'' (סֹבֵא) en la acusación de los padres contra un hijo rebelde, y Proverbios repite esta combinación (23:20-21; 28:7). En su sentido valorativo, significa ser despreciable o insignificante: Jeremías 15:19 contrasta lo ''vil'' (זוֹלֵל) con lo ''precioso'' (יָקָר), y Lamentaciones 1:11 usa el participio femenino para la Jerusalén caída. El puente semántico entre glotonería y vileza es la idea de abaratar o menospreciar algo valioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2152', 'spa', 'Calor abrasador, viento ardiente; indignación que consume', 'Sustantivo que evoca un calor intenso y destructivo, ya sea físico o emocional. Describe el «ardor del hambre» que oscurece la piel (Lam 5:10), el «viento abrasador» enviado como juicio divino junto con fuego y azufre (Sal 11:6), y la «ardiente indignación» que se apodera del salmista ante los impíos (Sal 119:53). Es calor que hiere: fiebre, siroco o furia. El núcleo semántico es una intensidad abrumadora y consumidora, sea meteorológica, corporal o moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2153', 'spa', 'Zilpá — sierva de Lea dada a Jacob como esposa, madre de Gad y Aser.', 'Zilpá fue la sierva que Labán dio a su hija Lea (Gn 29:24), y que Lea a su vez entregó a Jacob como esposa cuando creyó haber dejado de tener hijos (Gn 30:9). Mediante este arreglo, Zilpá dio a luz dos hijos, Gad y Aser, que llegaron a ser cabezas de tribus israelitas. Su nombre aparece en resúmenes genealógicos que vinculan a las doce tribus con sus madres (Gn 35:26; 46:18), subrayando que los doce hijos — sin importar la condición de sus madres — fueron igualmente reconocidos como herederos del pacto de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2154', 'spa', 'Lascivia, maldad, maquinación perversa -- depravación sexual, vileza moral o un plan deliberadamente malvado', 'Lascivia, maldad, maquinación perversa -- depravación sexual, vileza moral o un plan deliberadamente malvado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2155', 'spa', 'Zima (nombre propio; levita del clan gersonita)', 'Nombre levítico del clan gersonita que aparece en las listas genealógicas de Crónicas (1 Cr 6:20, 42; 2 Cr 29:12). Etimológicamente está relacionado con la palabra hebrea para «infamia» o «maldad», aunque en estos contextos funciona exclusivamente como identificador personal, sin connotación moral alguna. Las traducciones conservan el nombre (Zima en español, Zimmah en otras lenguas). Este caso ilustra la complejidad de la onomástica hebrea: no todos los nombres activan su significado etimológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2156', 'spa', 'Rama, sarmiento, brote; rama de vid, a veces figurativo de culto idolátrico', 'Sustantivo femenino que designa una rama o brote, típicamente de la vid. Los espías en Escol cortaron una זְמוֹרָה con un solo racimo de uvas (Nm 13:23), imagen vívida de la abundancia de la tierra. Ezequiel lo usa literalmente de la vid (15:2) y de manera enigmática de un objeto ritual acercado a la nariz en culto idolátrico (8:17). Isaías 17:10 habla metafóricamente de ''sarmientos de un dios extraño'', aludiendo a prácticas cultuales foráneas. Nahúm 2:2 aplica el plural figuradamente al pueblo de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2158', 'spa', 'Cántico o salmo de alabanza; composición musical que celebra a Dios o expresa triunfo.', 'Derivado de la raíz זָמַר (''cantar, hacer música''), este sustantivo designa un cántico o salmo, especialmente de alabanza o adoración. A David se le llama célebremente el ''dulce cantor de los cánticos de Israel'' (2 Sam 23:1), y los Salmos lo emplean para la adoración gozosa (Sal 95:2; 119:54). En Isaías también puede referirse a un cántico hostil de triunfo (Isa 25:5), lo que muestra que la palabra abarca todo el espectro de la música vocal compuesta, desde el himno devocional hasta el canto de victoria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2161', 'spa', 'Considerar, proponerse o maquinar; abarca desde la deliberación neutral hasta la intriga maliciosa', 'Verbo de intención mental que abarca el espectro desde la deliberación cuidadosa hasta el propósito firme y la maquinación maliciosa. Cuando Dios es el sujeto, describe un decreto soberano, como en Jeremías: ''lo he determinado y no me arrepentiré'' (Jer 4:28) y en el sombrío ''el SEÑOR ha hecho lo que determinó'' de Lamentaciones (Lm 2:17). Cuando los malhechores son el sujeto, el español ''maquinar'' y ''tramaron'' resaltan la connotación siniestra que adquiere en contextos como Deuteronomio 19:19 y Salmo 31:13. La única aparición en Proverbios 31:16, donde la mujer virtuosa ''considera'' un campo antes de comprarlo, revela el núcleo evaluativo neutral bajo los usos más dramáticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2163', 'spa', 'Fijado, señalado (referido a tiempos); participio Pual', 'Verbo del hebreo tardío (con influencia aramea) que aparece solo como participio Pual, describiendo tiempos «fijados» o «señalados». Se encuentra en las reformas cúlticas y administrativas de Esdras y Nehemías: «en tiempos señalados» para audiencias legales (Esd 10:14), para ofrendas de leña (Neh 10:34) y para ofrendas en fiestas establecidas (Neh 13:31). Es lenguaje litúrgico y burocrático: la ordenación del tiempo por decreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2165', 'spa', 'Tiempo señalado, estación; término hebreo tardío para un período fijo o designado, tomado del persa.', 'Sustantivo hebreo tardío que significa ''tiempo señalado'' o ''estación'', presente en libros postexílicos que reflejan influencia persa. En Neh 2:6, Nehemías fija un ''tiempo'' para su regreso ante el rey: una fecha específica y acordada. Eclesiastés 3:1 declara célebremente que hay un ''tiempo'' para todo bajo el cielo, empleando esta palabra para la estación establecida. En Ester 9:27, 31 designa los tiempos fijos de la observancia de Purim. Los cognados árabe zamān y etiópico zemen confirman su raíz semítica amplia, y el vocablo probablemente ingresó al hebreo a través del persa antiguo, reflejo del vocabulario administrativo del exilio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2166', 'spa', 'Tiempo, tiempo señalado (arameo) — una estación, ocasión o período definido; usado en Daniel y Esdras.', 'Tiempo, tiempo señalado (arameo) — una estación, ocasión o período definido; usado en Daniel y Esdras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2167', 'spa', 'Cantar alabanzas, hacer música — celebrar a Dios con canto y melodía instrumental (Piel de זָמַר)', 'Cantar alabanzas, hacer música — celebrar a Dios con canto y melodía instrumental (Piel de זָמַר)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2168', 'spa', 'podar, recortar (una viña); labor vitícola de poda', 'Verbo propio de la práctica vitícola: podar las vides. Aparece en la legislación del año sabático («podarás tu viña», Lev 25:3) y en su suspensión durante ese año («no podarás», Lev 25:4). Isaías profetiza una viña que «no será podada ni cavada» (Is 5:6), señalando su abandono. Se trata de un trabajo especializado: el corte cuidadoso que favorece la fecundidad de la planta. El término evoca el ritmo del cuidado agrícola y su cesación, ya sea por mandamiento divino o por juicio profético.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2170', 'spa', 'Música, canto instrumental; término arameo para la ejecución musical que acompañaba la imagen dorada de Nabucodonosor.', 'Sustantivo arameo en estado enfático (זְמָרָא), que aparece exclusivamente en Daniel 3 dentro del catálogo repetido de instrumentos que convocaban a la adoración de la imagen dorada de Nabucodonosor. El vocablo es cognado del conocido hebreo זָמַר (''hacer música, cantar alabanza'') y aquí denota la música en sentido general o colectivo: el sonido combinado de la orquesta. Sus cuatro apariciones forman parte de la fórmula: ''cuando oigáis el sonido del cuerno, la flauta, la lira... y toda clase de música''. Las traducciones multilingües lo confirman de manera directa como ''música''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2172', 'spa', 'Cántico, melodía o música ofrecida en alabanza; celebración instrumental o vocal de la grandeza de Dios.', 'Término para cántico o melodía, casi siempre dirigido a la alabanza de Dios. En el triunfal Cántico del Mar (Éx 15:2) aparece en la célebre declaración ''el Señor es mi fortaleza y mi cántico'', línea repetida textualmente en Isaías 12:2 y Salmo 118:14, lo que subraya su arraigo litúrgico. La palabra abarca tanto la música instrumental (Am 5:23, junto al arpa) como la celebración vocal (Is 51:3). Las traducciones multilingües coinciden en apuntar hacia la alabanza musical: ''cántico'' en español, ''cantique'' en francés, ''ein Lied'' en alemán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2174a', 'spa', 'Zimri — nombre propio hebreo de un príncipe simeonita, un rey de Israel y figuras de Judá y Benjamín', 'Nombre propio masculino que identifica al menos a cuatro individuos en la Biblia hebrea. El más prominente es el rey israelita que asesinó a Ela y reinó solo siete días antes de que el asedio de Omri lo llevara a la autoinmolación (1 R 16:9-20); la burla de Jezabel ''¿Tuviste paz, Zimri?'' (2 R 9:31) preserva su infamia como regicida. El nombre también pertenece al príncipe simeonita muerto por Finees en Baal-peor (Nm 25:14), a un nieto de Judá (1 Cr 2:6) y a un descendiente benjaminita de Saúl (1 Cr 8:36; 9:42).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2176', 'spa', 'melodía, cántico (especialmente en alabanza a Yahvé)', 'Sustantivo que designa la alabanza musical, ya sea instrumental o vocal. Aparece en convocatorias litúrgicas («Entonad un cántico; haced sonar el pandero, el arpa dulce con la lira», Sal 81:2), en la triple confesión «Yahvé es mi fortaleza y mi cántico» (Éx 15:2; Sal 118:14; Is 12:2), y en el sonido del arpa y la melodía (Sal 98:5). Es música ofrecida a Dios: gozosa, pública y frecuentemente acompañada de instrumentos. El término evoca adoración comunitaria y jubilosa, no lamento privado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2177', 'spa', 'clase, tipo, variedad (hebreo tardío)', 'Sustantivo del hebreo tardío que denota categorías o tipos. Aparece en el Salmo 144:13 («nuestros graneros llenos, que proveen toda clase de productos», lit. «de especie en especie») y en el relato del entierro de Asá con «diversas clases de especias» (2 Cr 16:14). Es el lenguaje de la abundancia y la variedad: no un solo tipo, sino todos los tipos, una plenitud que abarca múltiples categorías. Expresa diversidad taxonómica, la riqueza que se manifiesta en la multiplicidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2178', 'spa', 'Clase, tipo, género; usado en las porciones arameas de Daniel para categorías de instrumentos musicales.', 'Sustantivo arameo que significa ''clase'' o ''tipo'', presente exclusivamente en Daniel 3 dentro de la fórmula repetida que describe la orquesta de Nabucodonosor. Sus cuatro apariciones (Dan 3:5, 7, 10, 15) forman parte de la expresión ''toda clase de música'', enumerando los instrumentos cuyo sonido ordenaba postrarse ante la imagen dorada. Las traducciones multilingües confirman su sentido clasificatorio: ''tipo de'' en español, ''kinds of'' en inglés, ''Art'' en alemán. Su restricción a este único contexto arameo lo convierte en un término estrecho pero vívido para la agrupación por categorías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2180', 'spa', 'Cola — la extremidad posterior de un animal; figuradamente, la parte más baja, débil o insignificante', 'Cola — la extremidad posterior de un animal; figuradamente, la parte más baja, débil o insignificante');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2181', 'spa', 'Fornicar, prostituirse; en sentido figurado, ser espiritualmente infiel a Dios; como sustantivo, una prostituta; en Hifil, hacer que alguien se prosti', 'Fornicar, prostituirse; en sentido figurado, ser espiritualmente infiel a Dios; como sustantivo, una prostituta; en Hifil, hacer que alguien se prostituya.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2182', 'spa', 'Zanoa; topónimo de dos ciudades de Judá, una en la Sefela y otra en la serranía', 'Nombre propio que identifica dos ciudades en la heredad tribal de Judá. La primera Zanoa se encuentra en las tierras bajas de la Sefela, al sureste de Zora (Jos 15:34), y sus habitantes ayudaron a reconstruir la Puerta del Valle de Jerusalén bajo Nehemías (Neh 3:13; 11:30). La segunda Zanoa está situada en la serranía de Judá (Jos 15:56), posiblemente la actual Zanuta al suroeste de Hebrón. En 1 Crónicas 4:18 el nombre aparece en un contexto genealógico como asentamiento fundado por un descendiente de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2183', 'spa', 'Fornicaciones, prostituciones — infidelidad sexual habitual, usada literal y metafóricamente para la idolatría', 'Fornicaciones, prostituciones — infidelidad sexual habitual, usada literal y metafóricamente para la idolatría');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2184', 'spa', 'Fornicación, prostitución, infidelidad; sustantivo abstracto para la prostitución sexual o espiritual, especialmente la idolatría de Israel.', 'Sustantivo abstracto femenino que designa la fornicación o prostitución, usado tanto para la inmoralidad sexual literal como —de manera más prominente— para la infidelidad espiritual de Israel hacia YHWH. Los profetas Jeremías, Ezequiel y Oseas lo emplean como metáfora devastadora: Israel se ha prostituido con dioses extranjeros y alianzas foráneas. En Ezequiel 23:27, Dios promete poner fin a la zenut de Jerusalén, mientras que Oseas 4:11 advierte que el vino y el mosto quitan el entendimiento y conducen a la fornicación. La única aparición en la Torá (Nm 14:33) advierte que los hijos de la generación del desierto cargarán con las consecuencias de la prostitución espiritual de sus padres.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2186a', 'spa', 'Rechazar o desechar; usado cuando Dios repudia a su pueblo o cuando Israel rechaza lo bueno (Qal e Hifil).', 'Rechazar o desechar; usado cuando Dios repudia a su pueblo o cuando Israel rechaza lo bueno (Qal e Hifil).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2189', 'spa', 'Objeto de espanto u horror; cosa que causa terror, usado en maldiciones de juicio profético.', 'Este sustantivo describe algo tan terrible que hace temblar a los espectadores: un objeto de espanto. Aparece exclusivamente en contextos de maldición pactual y juicio profético donde Dios amenaza con convertir a un pueblo desobediente en un espectáculo de terror ante todas las naciones. La formulación clásica de Deuteronomio 28:25, «serás motivo de espanto para todos los reinos de la tierra», establece el patrón que Jeremías repite insistentemente (15:4; 24:9; 29:18; 34:17) al describir el destino de Judá y Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2191', 'spa', 'Un poco, una pequeña cantidad; referido a cantidad escasa o breve duración', 'Sustantivo diminutivo que significa ''un poco'', presente en dos contextos distintivos. En Isaías 28:10, 13 aparece en el estribillo burlón זְעֵיר שָׁם זְעֵיר שָׁם (''un poco aquí, un poco allá''), emparejado con צַו y קַו, imitando la percepción de los borrachos que veían la instrucción profética como un goteo tedioso. En Job 36:2, Elihú pide ''un poco'' de paciencia antes de continuar su argumento. La forma compacta de la palabra se ajusta a su significado: algo pequeño, ya sea en cantidad o en tiempo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2194', 'spa', 'Indignarse, denunciar o maldecir; expresión de ira divina o humana intensa, a menudo como condena profética formal', 'Indignarse, denunciar o maldecir; expresión de ira divina o humana intensa, a menudo como condena profética formal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2195', 'spa', 'Indignación, ira feroz; intenso desagrado que expresa típicamente la justa ira de Dios contra el pecado y la rebelión', 'Indignación, ira feroz; intenso desagrado que expresa típicamente la justa ira de Dios contra el pecado y la rebelión');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2196', 'spa', 'Estar irritado, malhumorado o enfurecido; expresar disgusto que va desde el abatimiento hasta la furia abierta', 'Verbo que abarca toda la gama emocional desde el disgusto silencioso hasta la ira desatada. En Génesis 40:6, José nota que los oficiales del faraón lucen abatidos (זֹעֲפִים), simplemente perturbados tras sueños inquietantes. Daniel 1:10 emplea el participio para describir un semblante demacrado y preocupado. En el extremo opuesto, 2 Crónicas 26:19 describe al rey Uzías enfureciéndose cuando los sacerdotes le confrontan por quemar incienso sin autorización. Proverbios 19:3 advierte que la necedad del hombre tuerce su camino, pero su corazón se irrita contra el SEÑOR.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2197', 'spa', 'Ira feroz, furia tempestuosa o indignación violenta — de reyes, de Dios o del mar embravecido.', 'Sustantivo poético y tardío que transmite una ira feroz y tempestuosa. Describe la cólera violenta del rey Asa, quien encarceló al vidente Hanani ''lleno de furor'' (2 Cr 16:10), y la furia del juicio divino (Isa 30:30; Miq 7:9). Proverbios compara la ira del rey con el rugido del león (Prov 19:12). De manera notable, Jonás 1:15 lo aplica al embravecimiento del mar, conectando la furia humana con la violencia indómita de la naturaleza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2199', 'spa', 'Clamar en angustia o súplica; en Nifal, ser convocado o reunido; en Hifil, convocar o proclamar en voz alta.', 'Clamar en angustia o súplica; en Nifal, ser convocado o reunido; en Hifil, convocar o proclamar en voz alta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2201', 'spa', 'Clamor o grito de angustia, que surge del sufrimiento, la opresión o la injusticia y se dirige hacia Dios.', 'Clamor o grito de angustia, que surge del sufrimiento, la opresión o la injusticia y se dirige hacia Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2203', 'spa', 'brea, alquitrán (sustancia bituminosa)', 'Sustantivo que designa la brea o el alquitrán, un agente impermeabilizante. La madre de Moisés «calafateó» su canasta «con betún y brea» (Éx 2:3), e Isaías profetiza que «los arroyos de Edom se convertirán en brea» y «su tierra será brea ardiente» (Is 34:9, dos veces). Se trata de una sustancia pegajosa e inflamable usada tanto para la preservación (la cesta de Moisés) como símbolo de juicio (la desolación de Edom). La brea evoca simultáneamente protección y destrucción: sellar la vida o sellar la condena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2204', 'spa', 'ser viejo, envejecer — verbo estativo que describe la condición o proceso de envejecimiento en patriarcas, reyes y ancianos', 'ser viejo, envejecer — verbo estativo que describe la condición o proceso de envejecimiento en patriarcas, reyes y ancianos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2205', 'spa', 'Viejo, anciano; un líder comunitario o miembro del consejo de ancianos; adjetivo de edad y título de autoridad cívica.', 'Pocas palabras hebreas cabalgan entre la descripción física y el rol social con tanta naturalidad como זָקֵן. Como simple adjetivo, describe a alguien de edad avanzada: Abraham y Sara son ''viejos, entrados en días'' (Gn 18:11). Pero en el plural constructo (''ancianos de Israel'', ''ancianos de la ciudad''), se convierte en término técnico de liderazgo para el consejo de hombres que gobernaba la vida tribal, cívica y nacional. Los ''ancianos de Israel'' aparecen desde Egipto (Éx 3:16) hasta el exilio. El árabe شيخ sigue exactamente la misma trayectoria semántica: un hombre mayor que se vuelve jefe tribal. El alemán distingue bien entre ''alt'' (viejo) y ''Älteste'' (ancianos), mientras que el español ''anciano'' preserva la misma ambigüedad productiva del hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2206', 'spa', 'Barba (o mentón): el vello facial del hombre, que significa dignidad, identidad y estatus ritual en la cultura israelita.', 'Barba (o mentón): el vello facial del hombre, que significa dignidad, identidad y estatus ritual en la cultura israelita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2208', 'spa', 'Vejez; usado exclusivamente en la expresión ''hijo de la vejez'' para un hijo nacido tardíamente.', 'Sustantivo plural que denota vejez, presente solo en Génesis dentro de la conmovedora expresión ''hijo de su vejez''. Aparece primero cuando Sara da a luz a Isaac para el anciano Abraham (Gn 21:2, 7), y resurge en la narrativa de Jacob: José es el amado ''hijo de su vejez'' (Gn 37:3), y Benjamín es descrito igualmente como ''hijo de la vejez'' (Gn 44:20). Las traducciones multilingües son uniformes: ''en su vejez'' en español, ''dans son ancien âge'' en francés, ''in seinem Alter'' en alemán, todas captando la ternura de un hijo nacido de padres ancianos. La palabra lleva una profunda carga emocional: estos hijos tardíos se convierten en figuras decisivas del relato bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2209', 'spa', 'Vejez; la etapa avanzada de la vida, frecuentemente asociada con las canas como signo de largos años vividos.', 'Sustantivo femenino que significa ''vejez'', empleado con frecuencia junto a ''canas'' (sevah) para evocar la plenitud de una vida larga. Aparece en súplicas conmovedoras de no ser abandonado en la vejez (Sal 71:9, 18), en el relato de Sara dando a luz a Isaac en su ancianidad (Gn 24:36) y al señalar la decadencia espiritual de Salomón ''en el tiempo de su vejez'' (1 R 11:4). La palabra marca una etapa reconocida de la vida que conlleva tanto honor como vulnerabilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2212', 'spa', 'Refinar o purificar, especialmente metales por fundición; también destilar lluvia y purificar el habla.', 'Un verbo que denota el proceso de separar impurezas mediante calor o filtrado, aplicado con mayor frecuencia al refinamiento de metales preciosos. El oro se refina (Job 28:1; 1 Cr 28:18), la plata se purifica siete veces (Sal 12:6) y la lluvia se destila de la niebla (Job 36:27). La palabra tiende un puente entre lo físico y lo espiritual: el mismo proceso de refinación que produce oro puro del mineral se convierte en metáfora de la purificación que Dios hace de sus promesas (Sal 12:6) y, en Isaías 25:6, de vinos añejos y filtrados servidos en el banquete escatológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2213', 'spa', 'Borde ornamental, moldura de oro — reborde decorativo o cornisa en el mobiliario del tabernáculo', 'Borde ornamental, moldura de oro — reborde decorativo o cornisa en el mobiliario del tabernáculo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2216', 'spa', 'Zorobabel — gobernador postexílico de Judá que lideró el retorno de Babilonia y reconstruyó el Templo', 'Zorobabel — gobernador postexílico de Judá que lideró el retorno de Babilonia y reconstruyó el Templo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2218', 'spa', 'Zered; un wadi (arroyo estacional) que marcó el límite cruzado por Israel camino a Canaán.', 'Nombre de un wadi —un cauce estacional— que Israel cruzó durante la travesía por el desierto, señalando un límite significativo entre territorios. Números 21:12 registra el campamento junto al wadi de Zered, y Deuteronomio 2:13-14 recuerda que habían transcurrido treinta y ocho años entre Cades-barnea y el cruce de Zered, período durante el cual pereció toda la generación de guerreros. Su ubicación exacta es debatida: los candidatos incluyen Wadi el-Ahsy entre Moab y Edom, o Wadi Kerak. Todas las traducciones lo presentan uniformemente como «Zered», confirmando su condición de topónimo establecido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2219', 'spa', 'Esparcir, aventar, dispersar; dispersar pueblos en juicio o lanzar grano al viento; también difundir o escudriñar', 'Esparcir, aventar, dispersar; dispersar pueblos en juicio o lanzar grano al viento; también difundir o escudriñar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2220', 'spa', 'Brazo, el miembro físico; en sentido figurado: poder divino o humano, fuerza, fuerzas militares; la espaldilla o pierna delantera de un animal sacrifi', 'Brazo, el miembro físico; en sentido figurado: poder divino o humano, fuerza, fuerzas militares; la espaldilla o pierna delantera de un animal sacrificial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2222a', 'spa', 'gotear, irrigar; verbo raro que posiblemente significa hacer caer lluvia o humedad', 'Este verbo poco frecuente aparece únicamente en una variante textual del Salmo 72, donde algunos estudiosos proponen leerlo en lugar de otra palabra igualmente rara. El significado sugerido implica gotear o irrigar, encajando con las imágenes agrícolas del salmo sobre un gobierno justo que trae bendición como lluvia sobre la hierba segada. La raíz posiblemente se relaciona con el árabe «derramar lágrimas» o el arameo «lluvia torrencial». Tales enmiendas textuales reflejan los esfuerzos académicos por resolver pasajes difíciles proponiendo vocablos hebreos alternativos con significados más transparentes. La presencia original de este verbo en el texto sigue siendo incierta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2224', 'spa', 'Salir (del sol o luminarias), resplandecer con radiancia divina, o brotar (de una condición cutánea).', 'Salir (del sol o luminarias), resplandecer con radiancia divina, o brotar (de una condición cutánea).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2226', 'spa', 'Zéraj — ''salida, amanecer''; nombre de varias figuras del AT, incluyendo un hijo de Judá y un jefe edomita', 'Zéraj — ''salida, amanecer''; nombre de varias figuras del AT, incluyendo un hijo de Judá y un jefe edomita');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2227', 'spa', 'Zerahíta — miembro del clan descendiente de Zérah, hijo de Judá (o de Simeón).', 'Adjetivo gentilicio que siempre aparece con el artículo definido, designando a un miembro del clan de Zérah. En la mayoría de los casos se refiere a descendientes de Zérah hijo de Judá (Nm 26:20; Jos 7:17; 1 Cr 27:11, 13), mientras que una ocurrencia remite a Zérah hijo de Simeón (Nm 26:13). El célebre episodio del pecado de Acán lo identifica mediante esta marca clánica (Jos 7:17), y los comandantes militares de David incluyen zerahítas en la rotación mensual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2228', 'spa', 'Zeraḥyah; nombre sacerdotal que significa ''Yah ha resplandecido'', en genealogías aaronitas y entre exiliados retornados', 'Nombre propio masculino que significa ''el SEÑOR ha resplandecido'' o ''el SEÑOR ha amanecido'', compuesto de זֶרַח (''amanecer, resplandecer'') y el nombre divino. Zeraḥyah aparece en la genealogía sacerdotal aaronita como descendiente de Eleazar y antepasado de Esdras (1 Cr 6:6, 51; Esd 7:4). En Esdras 8:4, un Zeraḥyah encabeza una familia entre los exiliados que retornan, posiblemente el mismo individuo o un descendiente. La Septuaginta lo transcribe uniformemente como Ζαραια.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2230', 'spa', 'Tormenta violenta, aguacero torrencial o diluvio de lluvia; usado en imaginería profética como juicio divino y fuerza abrumadora.', 'Este sustantivo evoca el aguacero repentino y violento que arrasa todo a su paso: lluvia que azota muros y barre valles montañosos. Isaías lo emplea repetidamente como metáfora del juicio divino y, a la inversa, del refugio que Dios ofrece contra él: ''un amparo contra la tormenta'' (Is 25:4), ''un abrigo contra la tempestad'' (Is 32:2). En Habacuc 3:10, los montes ven a Dios y se estremecen mientras pasa un torrente de aguas. Job 24:8 ofrece una imagen literal conmovedora: los pobres, sin refugio, quedan empapados por el aguacero de las montañas. La palabra captura el poder crudo e ingobernable de la naturaleza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2232', 'spa', 'Sembrar semilla, plantar; referido a la siembra agrícola, producir semilla (de las plantas), ser sembrado (pasivo) y concebir descendencia (figurado).', 'Sembrar semilla, plantar; referido a la siembra agrícola, producir semilla (de las plantas), ser sembrado (pasivo) y concebir descendencia (figurado).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2233', 'spa', 'Semilla, descendencia; semilla vegetal para la siembra, descendientes o linaje humano, y la época de la siembra.', 'זֶרַע es uno de los grandes sustantivos de doble función de la Biblia hebrea, abarcando lo agrícola y lo genealógico con una sola palabra. En Génesis 1 es la semilla dentro del fruto, el mecanismo de la reproducción botánica que Dios declara ''bueno''. Ya en Génesis 3:15 se ha convertido en la ''simiente de la mujer'': descendencia, progenie, portadora de promesa y amenaza a través de las generaciones. El pacto abrahámico gira en torno a זֶרַע: ''haré tu descendencia como el polvo de la tierra'' (Gn 13:16). La mayoría de las lenguas deben elegir entre vocabulario botánico y genealógico —el hindi distingue बीज de संतान, el coreano separa 씨 de 자손—, pero el hebreo los mantiene unidos en una sola palabra cuya ambigüedad es a veces teológicamente deliberada, como en las promesas mesiánicas de la ''simiente''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2236', 'spa', 'Lanzar, arrojar en cantidad — rociadura ritual de sangre/agua, o esparcimiento de material seco (polvo, ceniza, grano)', 'Lanzar, arrojar en cantidad — rociadura ritual de sangre/agua, o esparcimiento de material seco (polvo, ceniza, grano)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2238', 'spa', 'Zeres; esposa de Amán, quien primero alentó y luego lamentó su complot contra Mardoqueo.', 'Nombre propio de la esposa de Amán en el libro de Ester. Zeres aparece por primera vez aconsejando a su marido construir una horca para Mardoqueo (Est 5:10, 14), pero tras la humillación de Amán al tener que honrar públicamente a Mardoqueo por las calles, ella cambia de parecer y predice de forma ominosa la caída de su esposo (Est 6:13). El nombre posiblemente deriva de una palabra persa que significa «dorada» o podría estar relacionado con una diosa elamita, Kirisha. Las traducciones lo presentan de diversas formas —en inglés «Zeresh», en español «Zeres», en alemán «Seresch»— pero todas lo conservan como nombre personal reconocible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2239', 'spa', 'Palmo — distancia de la punta del pulgar a la del meñique con la mano extendida, aproximadamente medio codo.', 'El palmo (zeret) es una antigua unidad de medida lineal equivalente a aproximadamente medio codo, unos 22-23 centímetros, definida al extender la mano desde el pulgar hasta el meñique. Funciona como una medida concreta a escala humana: Dios mide los cielos a palmos (Is 40:12), la estatura de Goliat se indica como seis codos y un palmo (1 S 17:4), y el pectoral sacerdotal se describe como un palmo cuadrado (Éx 28:16; 39:9). El español palmo y el francés empan conservan la imaginería manual de esta medida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2240', 'spa', 'Zatu; cabeza de una familia entre los exiliados que regresaron de Babilonia.', 'Nombre propio que identifica al jefe de un clan que regresó del exilio babilónico. Zatu aparece en las listas censales de Esdras 2:8 y su paralelo en Nehemías 7:13, donde sus descendientes figuran entre la comunidad restaurada. Miembros de su familia también son mencionados entre quienes habían tomado esposas extranjeras (Esd 10:27), y el nombre figura en el documento sellado del pacto en Nehemías 10:14. Las traducciones en francés y alemán conservan la forma hebrea sin transliterar, mientras que el inglés y el español lo presentan como «Zattu» y «Zatu» respectivamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2244', 'spa', 'Esconderse, refugiarse (Nifal/Hitpael reflexivo); ser ocultado o estar escondido (Nifal/Hofal/Pual pasivo); esconder a alguien o algo (Hifil causativo', 'Esconderse, refugiarse (Nifal/Hitpael reflexivo); ser ocultado o estar escondido (Nifal/Hofal/Pual pasivo); esconder a alguien o algo (Hifil causativo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2247', 'spa', 'Retirarse, esconderse; refugiarse u ocultarse ante el peligro o el juicio', 'Verbo que significa retirarse u ocultarse, estrechamente emparentado con el más frecuente חָבָא. En Josué 2:16, Rajab ordena a los espías israelitas esconderse en los montes durante tres días. Isaías 26:20 formula un tierno imperativo — ''Ven, pueblo mío, entra en tus aposentos'' — evocando refugio divino durante el juicio venidero. Las formas nifal en 1 Reyes 22:25 y 2 Reyes 7:12 describen la acción de ocultarse en un cuarto interior, mientras que Jeremías 49:10 declara que Esaú no podrá esconderse del juicio escrutador de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2249', 'spa', 'Habor (nombre de río en Mesopotamia)', 'Río de la Alta Mesopotamia que desemboca en el Éufrates por el este. Se le llama «el río de Gozán» (2 R 17:6; 18:11) y aparece en el relato de la deportación asiria de los israelitas. En 1 Crónicas 5:26 se mencionan «Habor, Hara y el río de Gozán» (los dos primeros podrían ser variantes escribales del mismo nombre). El topónimo se conserva en las distintas traducciones (Habor, Jabor, Chavor). Es un marcador geográfico del exilio: el lugar donde Israel fue dispersado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2250', 'spa', 'Herida, llaga o cardenal causado por un golpe; lesión física producida al golpear o azotar.', 'Este sustantivo femenino designa la marca visible que deja un golpe violento: una herida, llaga o cardenal. Aparece en contextos que van desde la jactancia de Lamec por haber matado a un hombre que lo hirió (Gn 4:23) hasta la legislación del talión que prescribe llaga por llaga (Éx 21:25). Su uso más memorable se halla en Isaías 53:5, donde se declara que «por su llaga fuimos nosotros curados», reuniendo en un solo sustantivo colectivo todo el sufrimiento redentor del siervo. El término aparece constantemente junto a sinónimos de herida y lesión (פֶּצַע, מַכָּה), formando un campo léxico del trauma físico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2251', 'spa', 'Sacudir, varear (aceitunas del árbol); desgranar a golpes (grano con vara), distinto de la trilla a gran escala', 'Verbo referido a la cosecha a pequeña escala: describe el acto de varear aceitunas de las ramas o desgranar cereal golpeándolo con una vara, a diferencia de la trilla en era con ganado. Gedeón estaba desgranando trigo en un lagar para ocultarlo de los madianitas (Jue 6:11), y Rut desgranó lo que había espigado (Rut 2:17). En Isaías 27:12 la imagen se vuelve figurada: Yahvé sacudirá la cosecha desde el Éufrates hasta el torrente de Egipto, recogiendo a Israel uno por uno. El término implica siempre una acción percusiva y manual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2254a', 'spa', 'Tomar en prenda o embargar como garantía; el acto de retener la propiedad de un deudor como fianza', 'Tomar en prenda o embargar como garantía; el acto de retener la propiedad de un deudor como fianza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2254b', 'spa', 'Actuar corruptamente, destruir o arruinar; abarca desde la corrupción moral hasta la devastación activa y la destrucción pasiva.', 'Esta raíz porta una carga sombría de ruina, ya sea moral o física. En Nehemías 1:7, la nación confiesa «hemos actuado muy corruptamente contra ti», un uso del Qal que apunta a la descomposición moral. El Piel intensifica esto hacia la devastación activa: las pequeñas zorras que «arruinan» las viñas (Cnt 2:15), o el destructor que Dios formó para sus propósitos (Is 54:16). Las formas cognadas en arameo y asirio confirman el mismo espectro, desde herir hasta la ruina total. Los temas pasivos (Nifal/Pual) describen el resultado: ser quebrantado, roto o reducido a nada (Job 17:1, Pr 13:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2254c', 'spa', 'Estar de parto, sufrir dolores de parto; dar a luz con dolor (Piel)', 'Verbo que describe el dolor y el trabajo de parto. El impío «concibe aflicción y da a luz engaño» (Sal 7:14, uso metafórico del parto como imagen de la maldad gestada). En el Cantar, la madre de la amada «tuvo dolores de parto contigo» y «te dio a luz con dolor» (Cnt 8:5, dos veces). La palabra evoca el esfuerzo agónico de traer algo a la existencia, ya sea una vida nueva o una trama perversa, y abarca tanto el sentido físico como el figurado del alumbramiento doloroso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2255', 'spa', 'Destruir, arruinar; dañar, hacer daño (verbo arameo en Pael/Hitpaal en Daniel y Esdras).', 'Verbo arameo que aparece exclusivamente en Daniel y Esdras, usado en el tronco Pael con el sentido de ''destruir'' o ''arruinar'' y en el Hitpaal como ''ser destruido''. La palabra lleva un peso apocalíptico: el reino de Dios ''jamás será destruido'' (Dn 2:44; 7:14), mientras los poderes humanos se desmoronan. En Dn 6:22, se aplica de forma más suave a los leones que no ''hicieron daño'' a Daniel, mostrando que el verbo puede matizarse desde la aniquilación total hasta el simple daño físico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2256a', 'spa', 'Cuerda, soga o cordel de medir; por extensión, una porción medida de territorio, una herencia asignada, o un grupo de personas.', 'Cuerda, soga o cordel de medir; por extensión, una porción medida de territorio, una herencia asignada, o un grupo de personas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2256b', 'spa', 'Dolor, angustia, especialmente dolores de parto; metáfora profética de la agonía de las naciones y la crisis de la redención.', 'Distinguido de su homónimo que significa ''cuerda'' o ''territorio'', este hevel designa un dolor agudo, particularmente los dolores de parto. Los profetas recurren al parto como imagen suprema de una angustia abrumadora pero con propósito: Isaías describe naciones presa de dolores ''como mujer de parto'' (Is 13:8), y Oseas advierte que los dolores de parturienta vendrán sobre Efraín (Os 13:13). Sin embargo, los dolores de parto apuntan más allá del sufrimiento hacia una vida nueva: Isaías 66:7 se maravilla de que Sion diera a luz antes de que vinieran sus dolores. En Job, la palabra aparece tanto literalmente de animales pariendo (39:3) como metafóricamente de la calamidad humana (21:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2257', 'spa', 'Daño, perjuicio, lesión; arameo', 'Sustantivo arameo que designa daño o perjuicio. Aparece cuando los opositores advierten que una Jerusalén reconstruida causará «daño» a los ingresos reales (Esd 4:22), y en los relatos de Daniel sobre la protección divina: los hombres en el horno de fuego no sufren «daño alguno» (Dn 3:25) y Daniel sale del foso de los leones «sin lesión» (Dn 6:23). Es un término tanto administrativo como narrativo que abarca el daño financiero y el físico, y evoca la amenaza del perjuicio y la liberación de él.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2258a', 'spa', 'Prenda, garantía (como fianza por una deuda)', 'Sustantivo que designa la prenda entregada como garantía de un préstamo. Aparece en las descripciones de Ezequiel sobre la conducta del justo y del impío: el justo «devuelve la prenda» (Ez 18:16; 33:15), mientras que el impío la retiene (Ez 18:12). Derivado del verbo «atar», refleja la práctica jurídico-económica de retener una garantía material. Es lenguaje de pacto y comercio: lo que vincula al deudor con el acreedor y lo que la justicia exige que sea restituido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2259', 'spa', 'Marinero, piloto, timonel; quien maneja las cuerdas de un navío', 'Derivado del sustantivo חֶבֶל (''cuerda''), este término significa literalmente ''el que tira de las cuerdas'' y designa a un marinero o piloto de navío. Aparece exclusivamente en contextos marítimos: el lamento de Ezequiel sobre Tiro menciona a sus pilotos y marineros experimentados (Ez 27:8, 27-29), mientras que en Jonás 1:6 el ''jefe de los pilotos'' (רַב הַחֹבֵל) es el capitán del barco que despierta al profeta dormido. El término apunta siempre a navegantes experimentados, no a simples pasajeros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2263', 'spa', 'Abrazar o estrechar; usado para saludar afectuosamente a alguien, o para cruzar los brazos en ociosidad', 'Verbo que expresa el acto físico de rodear con los brazos a otra persona, principalmente en contextos de saludo afectuoso y reencuentro. Jacob abraza a Labán (Gn 29:13), Esaú abraza a Jacob (Gn 33:4) y el anciano Israel abraza a los hijos de José (Gn 48:10). El Piel intensivo transmite calidez y deliberación. Un uso idiomático distinto aparece en Eclesiastés 4:5, donde el necio ''cruza sus manos'' en pereza, metáfora atestiguada en la literatura sapiencial. El español ''abrazar'' traduce consistentemente el abrazo interpersonal, mientras que la expresión de ociosidad recibe vocabulario especializado como ''cruza''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2266', 'spa', 'Unir, juntar, atar; de conexión física, alianza política, o lanzar hechizos y encantamientos mágicos', 'Unir, juntar, atar; de conexión física, alianza política, o lanzar hechizos y encantamientos mágicos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2267', 'spa', 'Compañía o asociación de personas; también hechizo o encantamiento — un conjuro prohibido en la ley deuteronómica.', 'Este sustantivo porta dos cargas semánticas distintas enraizadas en la idea de «atar o unir». En su sentido social concreto, designa una compañía, grupo o asociación de personas, ya sea el hogar compartido de Proverbios 21:9 y 25:24, o la banda merodeadora de sacerdotes en Oseas 6:9. En su sentido mágico, se refiere a un hechizo o encantamiento, un conjuro que «ata» fuerzas sobrenaturales. Deuteronomio 18:11 prohíbe el uso de tales hechizos junto con la nigromancia y la adivinación. Isaías 47:9 y 47:12 se burlan de la confianza de Babilonia en sus abundantes encantamientos, que no podrán salvarla del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2268', 'spa', 'Heber/Cheber — nombre propio que significa ''asociado, compañero''; llevado por varios varones israelitas.', 'El nombre propio חֶבֶר (Chever) deriva de la raíz חבר (''unir, asociar'') y lo portan al menos cuatro individuos distintos en las Escrituras. El más destacado es Heber el ceneo, esposo de Jael, quien se había separado de los demás ceneos y plantó su tienda cerca de Cedes (Jue 4:11, 17). Fue a su tienda adonde huyó Sísara, solo para ser muerto por Jael (Jue 4:21; 5:24). Otros portadores incluyen un nieto de Aser registrado en la familia de Jacob (Gn 46:17; Nm 26:45), un judahíta vinculado a Soco (1 Cr 4:18) y un benjaminita en la genealogía de Elpaal (1 Cr 8:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2269', 'spa', 'Compañero, colega; arameo', 'Sustantivo arameo que designa a un compañero o asociado. Aparece en el relato de Daniel sobre la crisis del sueño: el decreto de matar a «Daniel y sus compañeros» (Dn 2:13), y la súplica de Daniel pidiendo «misericordia acerca de este misterio para Daniel y sus compañeros» (Dn 2:17, 18). Es lenguaje de solidaridad: quienes comparten el destino y la fe de Daniel, unidos ante el decreto del rey. La palabra evoca camaradería forjada en la adversidad y el apoyo mutuo entre iguales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2270', 'spa', 'Compañero, asociado; como adjetivo, unidos o vinculados entre sí — alguien ligado por comunión, rango o propósito.', 'Derivado de la raíz que significa ''unir'' o ''atar juntos'', esta palabra describe a alguien que es compañero, colega o asociado — una persona vinculada por vocación, rango o propósito pactual compartido. En el Salmo 45:7 distingue al rey ungido de sus pares reales; en Cantares 1:7 la amada pregunta dónde apacienta su pastor entre sus compañeros pastores. Las traducciones al español lo rinden consistentemente como ''compañero'', mientras que el francés usa ''ami'', ambos capturando la calidez de la asociación. En Jueces 20:11, la única aparición adjetival describe a todo Israel reunido ''unidos como un solo hombre'', preservando la fuerza vinculante de la raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2275a', 'spa', 'Hebrón — una antigua ciudad en las montañas de Judá con profundas asociaciones patriarcales.', 'Hebrón — una antigua ciudad en las montañas de Judá con profundas asociaciones patriarcales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2275b', 'spa', 'Hebrón — nombre propio, hijo de Coat y nieto de Leví; antepasado de un clan levítico.', 'Este חֶבְרוֹן (Chevrón) no designa la famosa ciudad judía, sino a una persona: el tercer hijo de Coat, nieto de Leví y antepasado del clan hebronita (1 Cr 26:23). Aparece en las genealogías levíticas junto a sus hermanos Amram, Izhar y Uziel (Éx 6:18; Nm 3:19; 1 Cr 6:2, 18; 23:12, 19). Sus descendientes, los hebronitas, recibieron responsabilidades administrativas al oeste del Jordán bajo el reinado de David (1 Cr 26:30-32). El nombre personal es idéntico en forma al topónimo, por lo que se requiere contexto para desambiguarlos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2276', 'spa', 'Hebronita — miembro del clan levítico descendiente de Hebrón hijo de Coat.', 'Adjetivo gentilicio que identifica a los miembros de la familia levítica descendiente de Hebrón, hijo de Coat. Siempre se usa con el artículo como sustantivo colectivo y aparece exclusivamente en contextos administrativos y cultuales: el censo de familias levíticas (Nm 3:27; 26:58) y la organización de los deberes del templo por parte de David (1 Cr 26:23, 30, 31). A los hebronitas se les asignaron responsabilidades tanto dentro del santuario como en la administración civil al oeste y al este del Jordán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2279', 'spa', 'Pieza de unión o acoplamiento; el borde donde dos conjuntos de cortinas del tabernáculo se sujetan entre sí.', 'Término técnico de los pasajes de construcción del tabernáculo que designa el punto o pieza donde las secciones de cortinas se unen entre sí. Aparece exclusivamente en Éxodo 26 y 36, describiendo cómo las dos mitades de la cubierta del tabernáculo se acoplaban en sus bordes mediante lazadas y broches. La palabra deriva de la raíz que significa «juntar» o «atar», y su uso especializado la convierte en una ventana al vocabulario preciso de artesanía de los textos del santuario pentateuco. Las glosas multilingües captan bien su sentido funcional: en español «la que une», en inglés «the joining», en francés «le joignant».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2280', 'spa', 'Atar, vendar, ensillar; de vendar heridas, ensillar animales, envolver con tela, y contener o gobernar', 'Atar, vendar, ensillar; de vendar heridas, ensillar animales, envolver con tela, y contener o gobernar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2282', 'spa', 'Una fiesta sagrada o festividad de peregrinación, especialmente las tres celebraciones anuales de peregrinaje; por metonimia, el sacrificio festivo mi', 'Una fiesta sagrada o festividad de peregrinación, especialmente las tres celebraciones anuales de peregrinaje; por metonimia, el sacrificio festivo mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2284', 'spa', 'Langosta, saltamontes; especie pequeña de insecto no volador, usada como figura de insignificancia', 'Uno de varios términos hebreos para insectos del tipo langosta, esta palabra probablemente designa una especie más pequeña y no voladora, permitida como alimento en las leyes dietéticas levíticas (Lv 11:22). Su uso más memorable es el informe autodespreciativo de los espías israelitas: ''Éramos como langostas ante nuestros propios ojos'' (Nm 13:33). Isaías emplea la misma imagen a escala cósmica: los habitantes de la tierra son como saltamontes ante Dios (Is 40:22). En español se usan tanto ''langosta'' como ''saltamontes'', reflejando el rango semántico entre plaga y criatura diminuta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2287', 'spa', 'Celebrar una fiesta de peregrinación o festival; por extensión, tambalearse o vacilar.', 'Celebrar una fiesta de peregrinación o festival; por extensión, tambalearse o vacilar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2288', 'spa', 'Hendiduras, grietas (de la roca); lugares de ocultamiento', 'Sustantivo que designa fisuras estrechas o hendiduras en la roca que sirven como escondite. La amada es llamada «paloma mía, en las hendiduras de la peña» (Cnt 2:14), una imagen tierna de intimidad y refugio. Pero la misma imagen se torna ominosa en el juicio profético: Edom, que «mora en las hendiduras de la peña» (Jer 49:16; Abd 3), confía en fortalezas inaccesibles, pero será derribado. Las hendiduras ofrecen seguridad o la ilusión de ella, según quién busque amparo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2290b', 'spa', 'Cinturón, ceñidor, taparrabos; prenda ceñida a la cintura para recato o preparación militar', 'Este sustantivo designa una prenda atada alrededor de la cintura, cuyo rango semántico abarca desde los primitivos taparrabos de hojas de higuera que Adán y Eva improvisaron (Gn 3:7) hasta el cinturón militar del guerrero (1 R 2:5; 2 R 3:21). Isaías 3:24 lo incluye entre los artículos de fina vestimenta femenina que serán despojados en el juicio. La tensión entre el recato de emergencia y el equipamiento marcial se refleja en la evidencia multilingüe: el alemán ''Schürze'' (delantal/taparrabos) frente al español ''cinturón'' y el francés ''ceinture''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2291', 'spa', 'Hagui (nombre propio); haguita (gentilicio del clan de Hagui)', 'Nombre propio y gentilicio. Hagui fue hijo de Gad (Gn 46:16) y ancestro epónimo del clan de los haguitas (Nm 26:15, dos veces). El nombre significa «festivo» y aparece en listas censales y genealógicas. Es un ejemplo del patrón onomástico israelita típico: un nombre personal se convierte en marcador de identidad tribal, trazando la descendencia desde Jacob, pasando por Gad, hasta la familia de Hagui. Las traducciones conservan el nombre en distintas formas (Hagui, Jagi).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2292a', 'spa', 'Hageo: el profeta postexílico cuyos oráculos instaron a la reconstrucción del templo de Jerusalén (520 a.C.).', 'Hageo, cuyo nombre significa ''festivo'' o ''nacido en día de fiesta'', fue un profeta activo en el segundo año del rey persa Darío (520 a.C.). Sus oráculos breves pero incisivos, conservados en los dos capítulos que llevan su nombre, desafiaron a los exiliados retornados a dejar de descuidar el templo en ruinas y reconstruirlo. Es mencionado junto con Zacarías en Esdras 5:1 y 6:14 como una de las voces proféticas que impulsaron a la comunidad a completar el Segundo Templo. La forma griega de su nombre, Haggaios, se refleja en la Septuaginta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2294', 'spa', 'Jaguit; esposa de David y madre de Adonías, nombre que significa ''festiva'' o ''nacida en día de fiesta''', 'Nombre propio que significa ''festiva'', Jaguit fue una de las esposas de David y madre de Adonías, quien más tarde intentó reclamar el trono. Aparece en la narrativa de sucesión que rodea el ascenso de Salomón al reinado (1 R 1:5, 11; 2:13) y en los registros genealógicos de los hijos de David nacidos en Hebrón (2 S 3:4; 1 Cr 3:2). El nombre deriva de la raíz חַג (''fiesta/festival''), lo que sugiere que pudo haber nacido durante una festividad de peregrinación. La Septuaginta lo transcribe como Angit.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2295', 'spa', 'Hogla; hija de Zelofehad de Manasés, cuya reclamación de herencia estableció los derechos de propiedad femeninos.', 'Nombre propio que significa «perdiz», llevado por una de las cinco hijas de Zelofehad de la tribu de Manasés. Hogla y sus hermanas presentaron ante Moisés la célebre petición de herencia en la Tierra Prometida, dado que su padre había muerto sin hijos varones (Nm 27:1), y su caso se convirtió en un precedente legal para la herencia femenina en Israel. Aparece en la lista genealógica (Nm 26:33), en la petición inicial, en la estipulación matrimonial que exigía casarse dentro de la tribu (Nm 36:11) y en la asignación de tierras en Josué 17:3. Las traducciones suelen presentar el nombre como Hogla o Joglá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2296', 'spa', 'Ceñir, atar alrededor del cuerpo (un cinturón, espada, cilicio o prenda); en uso estativo, estar ceñido o equipado', 'Ceñir, atar alrededor del cuerpo (un cinturón, espada, cilicio o prenda); en uso estativo, estar ceñido o equipado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2298', 'spa', 'Numeral arameo ''uno''; raramente adverbial ''juntos, como uno solo''.', 'El equivalente arameo del hebreo ''echad'', este numeral aparece exclusivamente en las porciones arameas de Esdras y Daniel. En casi todas sus apariciones funciona directamente como el número cardinal ''uno'' — una carta (Esdras 4:8), un decreto (Esdras 6:2), un reino. Su único uso adverbial en Daniel 2:35, donde los materiales de la estatua destruida se quiebran ''juntos'' como tamo, revela cómo el concepto de ''unidad'' se extiende naturalmente a ''colectividad'' en las lenguas semíticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2299', 'spa', 'Afilado, agudo; describe una espada, lengua o boca como cortante y penetrante.', 'Adjetivo que significa ''afilado'' o ''agudo'', empleado tanto en sentido literal como figurado con gran fuerza expresiva. Ezequiel 5:1 lo usa literalmente para una espada afilada (o navaja), mientras que los Salmos y los Profetas lo despliegan metafóricamente: la lengua es ''afilada'' como espada (Sal 57:4) y la boca del siervo de Dios se compara con una espada aguzada (Is 49:2). De modo especialmente impactante, Proverbios 5:4 advierte que el final de la mujer ajena es ''agudo como espada de dos filos''. La imagen concreta de un filo cortante recorre todos estos usos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2300a', 'spa', 'Ser afilado o aguzado; de una espada preparada para la matanza, o caballos más feroces que lobos.', 'Verbo que significa ''ser o hacer afilado'', presente en contextos de terrible preparación para la violencia. En Ezequiel 21, el estribillo repetido ''la espada está afilada'' (vv. 9-11) construye un crescendo aterrador conforme la espada del juicio divino se prepara para la matanza: pulida y aguzada, entregada al verdugo. Habacuc 1:8 traslada la imagen a la caballería caldea, cuyos caballos son ''más feroces que lobos nocturnos'', transmitiendo una rapidez depredadora. Las cuatro apariciones comparten la noción de un filo letal listo para actuar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2302', 'spa', 'regocijarse, alegrarse; voz aramea/hebrea tardía que expresa gozo profundo', 'Verbo que expresa gozo y alegría. Jetro «se alegró» por todo el bien que el SEÑOR había hecho a Israel (Ex 18:9), Job maldice el día de su nacimiento deseando que «no se cuente entre los días del año» (Job 3:6), y el salmista declara que Dios «lo llena de alegría con su presencia» (Sal 21:6). No se trata de una felicidad superficial, sino de una respuesta profunda ante la bondad divina, ya sea la liberación de Dios o el don de la vida misma, o su trágica ausencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2307', 'spa', 'Hadid (topónimo en Benjamín)', 'Nombre de una ciudad en el territorio de Benjamín, mencionada junto con Lod y Ono en las listas censales postexílicas (Esd 2:33; Neh 7:37; 11:34). Se identifica con la moderna El-Haditheh, a pocos kilómetros al noreste de Lida. El nombre aparece en contextos administrativos: el conteo de los que regresaron del exilio y las ciudades repobladas. Es la geografía de la restauración: pequeñas ciudades que vuelven a cobrar vida tras el destierro, cuyos nombres forman una letanía de esperanza y retorno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2308', 'spa', 'Cesar, detenerse, desistir, abstenerse; dejar de hacer algo o dejar en paz a alguien; faltar o carecer.', 'Cesar, detenerse, desistir, abstenerse; dejar de hacer algo o dejar en paz a alguien; faltar o carecer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2310', 'spa', 'que cesa, transitorio; desamparado, carente', 'Adjetivo que denota ausencia o cesación. El salmista pide: «hazme saber cuán frágil soy» (Sal 39:4, o «cuán efímero»). Isaías describe al Siervo como «despreciado y desechado entre los hombres» (Is 53:3, lit. «carente de hombres» o «desamparado por los hombres»). Ezequiel distingue entre el que escucha y «el que se niega a escuchar» (Ez 3:27). La palabra abarca tanto la dimensión temporal —lo que es fugaz— como la relacional —lo que es abandonado—, evocando carencia, ya sea de tiempo, de apoyo o de obediencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2315', 'spa', 'Cuarto, cámara interior — una habitación privada dentro de un edificio, usada para dormir, recogimiento u ocultamiento', 'Cuarto, cámara interior — una habitación privada dentro de un edificio, usada para dormir, recogimiento u ocultamiento');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2316', 'spa', 'Hadad, nombre propio; hijo ismaelita cuyo nombre incorpora al dios de la tormenta', 'Este descendiente de Ismael lleva un nombre que invoca a la deidad aramea de la tormenta, común en las culturas del antiguo Cercano Oriente. El nombre aparece en el registro genealógico de Génesis entre los doce hijos de Ismael que se convirtieron en jefes tribales. Existen variantes textuales: algunos manuscritos leen Hadar, lo que refleja incertidumbre escribal o diferencias en la pronunciación regional. Las transliteraciones de la Septuaginta varían, sugiriendo que la forma del nombre no estaba perfectamente estandarizada. Tales nombres teofóricos, que incorporan nombres de deidades, eran habituales independientemente del dios que la familia adorara, representando a menudo herencia cultural más que devoción activa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2318', 'spa', 'Renovar, reparar, restaurar — hacer nuevo de nuevo, ya sea físicamente (edificios) o espiritualmente (vida interior).', 'El verbo חָדַשׁ (chadash), empleado exclusivamente en los temas Piel e Hitpael, significa renovar, reparar o restaurar algo a un estado nuevo. Su rango semántico abarca lo físico —reparar el templo (2 Cr 24:4, 12) y restaurar un altar (2 Cr 15:8)— y lo profundamente espiritual —la súplica de David por un espíritu renovado (Sal 51:12) y la renovación divina de la faz de la tierra (Sal 104:30). El llamado de Samuel a «renovar el reino» en Gilgal (1 S 11:14) porta una fuerza político-pactal. La raíz subyace a חָדָשׁ (nuevo) y חֹדֶשׁ (luna nueva/mes).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2319', 'spa', 'nuevo, fresco — hecho recientemente, que no existía antes, o renovado en calidad y propósito', 'nuevo, fresco — hecho recientemente, que no existía antes, o renovado en calidad y propósito');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2320', 'spa', 'Mes (período del calendario lunar) o luna nueva (fiesta que marca el primer día del mes).', 'Derivado de la raíz que significa ''nuevo'', חֹדֶשׁ tiende un puente entre la astronomía y el calendario en el antiguo Israel. En su sentido principal (260 ocurrencias), simplemente significa ''mes'': la unidad básica del calendario lunar hebreo, como en ''el mes segundo, a los diecisiete días'' (Gn 7:11). Pero en 23 pasajes, חֹדֶשׁ conserva su fuerza etimológica de ''luna nueva'', designando la fiesta observada en cada renovación lunar. La luna nueva era una ocasión religiosa significativa, emparejada con los sábados en la crítica profética (Is 1:13-14) y central en la narrativa de la mesa de David (1 S 20:5, 18, 24). El alemán ''Neumond'' y el francés ''nouvelle lune'' captan esta dimensión astronómico-litúrgica que el inglés ''month'' pierde por completo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2324', 'spa', 'Verbo arameo: mostrar o hacer visible; también declarar o anunciar verbalmente.', 'Un verbo arameo que se encuentra exclusivamente en Daniel, usado en las formas Pa''el y Haph''el para describir actos de revelar conocimiento oculto. Aparece con mayor urgencia en la crisis de interpretación de sueños de Daniel 2, donde el rey exige que sus sabios le ''muestren'' tanto el sueño como su significado. La palabra abarca tanto la demostración visual como la declaración verbal, aunque el contexto y la conjugación distinguen estos matices. Sus cognados en siríaco y hebreo bíblico (III חָוָה) confirman un significado raíz de hacer algo evidente o conocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2329', 'spa', 'círculo, bóveda, horizonte (de la tierra o los cielos)', 'Sustantivo que designa la bóveda circular o el horizonte del cosmos. Dios «está sentado sobre el círculo de la tierra» (Is 40:22), «trazó un círculo sobre la faz del abismo» en la creación (Pr 8:27), y «camina sobre la bóveda del cielo» (Job 22:14). La palabra evoca tanto el horizonte bidimensional como la cúpula tridimensional. Es lenguaje cosmológico: la geometría de la creación, donde el trono de Dios trasciende la esfera limitada del mundo, afirmando su soberanía sobre todo lo creado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2330', 'spa', 'Proponer o plantear un enigma; usado exclusivamente con el acusativo cognado חִידָה en contextos de adivinanzas.', 'Verbo especializado que significa proponer o plantear un enigma, y que siempre aparece junto a su sustantivo cognado חִידָה (enigma, adivinanza). Se encuentra casi exclusivamente en la narrativa de Sansón (Jue 14), donde describe el acto de desafiar a otros con un acertijo durante su banquete de bodas. Ezequiel 17:2 extiende este uso al discurso profético, donde Dios ordena al profeta ''proponer un enigma'' emparejándolo con מָשָׁל (parábola), señalando que lo que sigue tiene un significado deliberadamente encubierto. El campo semántico se mantiene ceñido al acto performativo de formular enigmas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2331', 'spa', 'Declarar, anunciar, dar a conocer — verbo poético de influencia aramea usado para proclamar sabiduría o verdad.', 'Verbo que se encuentra únicamente en el tronco Piel en textos poéticos y tardíos, con el significado de ''declarar'' o ''dar a conocer''. Como préstamo del arameo (cognado de chavvei), posee una cualidad formal y deliberada de proclamación. Elihú lo emplea repetidamente en Job para introducir sus declaraciones de sabiduría (Job 15:17; 32:6, 10, 17; 36:2). Los Salmos lo utilizan para describir cómo los cielos declaran conocimiento noche tras noche (Sal 19:3), otorgándole al vocablo un alcance cósmico junto a su uso humano y forense.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2333', 'spa', 'Aldea de tiendas o campamento; conjunto de asentamientos nómadas, especialmente en la frase חַוֹּת יָאִיר.', 'Se refiere a pequeñas aldeas sin murallas — asentamientos temporales o semipermanentes propios de la vida pastoril en Galaad y Basán. Aparece casi siempre en el nombre compuesto חַוֹּת יָאִיר (Havot-Jair, ''las aldeas de Jair''), preservando la memoria de los patrones de asentamiento israelita al este del Jordán durante los primeros tiempos. El término evoca comunidades rurales pequeñas, no ciudades fortificadas: agrupaciones de tiendas o chozas organizadas por parentesco, reflejo de un modo de vida seminómada en las tierras altas de Transjordania.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2334', 'spa', 'Havot-Jaír: aldeas de tiendas de Jaír en Galaad', 'Este nombre propio designa un grupo de aldeas de tiendas en Galaad vinculadas a Jaír, descendiente de Manasés. El nombre significa literalmente «aldeas de tiendas de Jaír». Estos asentamientos surgieron cuando Jaír conquistó ciertas ciudades en la región de Basán y Galaad, dándoles su propio nombre. El término aparece principalmente en descripciones territoriales de la Transjordania, marcando un punto fronterizo significativo en el período temprano de asentamiento de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2336', 'spa', 'Espino, zarza o abrojo (planta espinosa); también gancho o argolla para capturar y sujetar cautivos.', 'Una palabra con dos referentes notablemente distintos unidos por una misma propiedad física: algo agudo que atrapa y retiene. Como planta, designa espinos, zarzas o abrojos, la imagen bíblica clásica de desolación y tierra maldita. En la mordaz alegoría de Joás, el espino pretende negociar con el cedro del Líbano (2 R 14:9). Cantares 2:2 ofrece un cumplido inolvidable: «Como lirio entre espinos, así es mi amada entre las doncellas». Isaías y Oseas emplean los espinos como señales del juicio divino que invade los lugares abandonados. El segundo sentido —un gancho o argolla para conducir cautivos— aparece cuando los asirios capturan a Manasés «con ganchos» (2 Cr 33:11) y en el desafío de Job 41:2 sobre atrapar al Leviatán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2339', 'spa', 'Hilo, cordón o cuerda — una fibra delgada usada para atar, marcar o medir.', 'Sustantivo versátil que abarca desde un simple hilo hasta una cuerda de medir. Abraham jura que no tomará ni un hilo ni una correa de sandalia del rey de Sodoma (Gn 14:23), mientras que Rajab cuelga un cordón de hilo escarlata de su ventana como señal de salvación (Jos 2:18). El Cantar de los Cantares compara los labios con un hilo escarlata (4:3), y Eclesiastés observa que un cordón de tres hilos no se rompe fácilmente (4:12). Ya sea en sentido literal o figurado, el término evoca algo delgado pero con propósito definido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2340', 'spa', 'Heveo — uno de los pueblos cananeos enumerados entre los habitantes preisraelitas de la tierra de Canaán', 'Heveo — uno de los pueblos cananeos enumerados entre los habitantes preisraelitas de la tierra de Canaán');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2341', 'spa', 'Havilá — tierra o pueblo asociado con el oro y materiales preciosos, presente en contextos primigenios y genealógicos.', 'Havilá aparece en la Biblia hebrea tanto como región geográfica como grupo étnico. En el relato primigenio, es la tierra rica en oro rodeada por el río Pisón (Gn 2:11), asociada con bedelio y ónice. En la Tabla de las Naciones figura como hijo de Cus (Gn 10:7; 1 Cr 1:9) y como descendiente de Joctán por la línea de Sem (Gn 10:29; 1 Cr 1:23), lo que sugiere que el nombre designaba un territorio amplio, posiblemente arábigo. La frase «desde Havilá hasta Shur» (Gn 25:18; 1 S 15:7) marca la extensión del territorio ismaelita y amalecita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2342a', 'spa', 'girar, retorcerse, temblar, danzar; retorcerse de dolor o de parto; dar a luz, nacer; esperar', 'girar, retorcerse, temblar, danzar; retorcerse de dolor o de parto; dar a luz, nacer; esperar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2344', 'spa', 'Arena; material granular de la orilla del mar, usado abrumadoramente como figura de cantidad innumerable o peso inmenso', 'Arena; material granular de la orilla del mar, usado abrumadoramente como figura de cantidad innumerable o peso inmenso');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2345', 'spa', 'De color oscuro, pardo o negro; usado exclusivamente del color de ovejas en las negociaciones del rebaño de Jacob.', 'Adjetivo que describe un color pardo oscuro o negro, presente únicamente en la narrativa de Jacob y Labán sobre la división del rebaño en Génesis 30. Jacob propone separar todo cordero de color oscuro como su salario, empleando este término para marcar la distinción entre animales claros y oscuros. La palabra es notablemente específica: nunca aparece fuera de este contexto pastoril. Su sentido apunta a un color terroso y natural, sin la connotación de oscuridad moral que poseen otros vocablos hebreos para lo oscuro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2346', 'spa', 'Muralla — muro defensivo que rodea una ciudad, principal fortificación y símbolo de seguridad urbana en el antiguo Israel.', 'חוֹמָה es el término hebreo estándar para la muralla defensiva de una ciudad, con 133 ocurrencias. A diferencia del más genérico קִיר (cualquier pared, incluidos tabiques interiores), חוֹמָה designa específicamente el macizo perímetro de piedra que definía y protegía un asentamiento urbano. La palabra aparece en momentos cruciales: la casa de Rahab estaba empotrada en la חוֹמָה de Jericó (Jos 2:15), cuyas murallas se derrumbaron célebremente (Jos 6:5, 20); Nehemías reconstruyó la חוֹמָה de Jerusalén como acto de restauración nacional (Neh 2:17; 3:1-32; 12:27). Metafóricamente, una muralla representa seguridad, y su brecha significa juicio: ''Derribaré el muro de esta ciudad'' (Jer 1:15; Ez 26:9-10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2347', 'spa', 'Compadecerse, tener compasión; perdonar de la destrucción; mirar con pesar la pérdida de algo', 'Compadecerse, tener compasión; perdonar de la destrucción; mirar con pesar la pérdida de algo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2348', 'spa', 'Costa o ribera — la franja de tierra que bordea el mar, usada en descripciones geográficas de la Tierra Prometida.', 'Sustantivo que significa costa o ribera, que siempre aparece en forma constructa para describir la tierra que bordea el Mediterráneo u otros cuerpos de agua. La bendición de Jacob sitúa a Zabulón en la «costa del mar» y la «costa de navíos» (Gn 49:13), y la descripción de los límites de la Tierra Prometida incluye «la costa del Gran Mar» (Dt 1:7; Jos 9:1). El cántico de Débora señala que Dan se quedó junto a sus naves en la costa (Jue 5:17). En contextos proféticos, Jeremías y Ezequiel invocan la costa como escenario del juicio divino contra los filisteos (Jer 47:7; Ez 25:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2351', 'spa', 'El exterior, el espacio fuera de un edificio, campamento o ciudad; en plural, calles o plazas públicas; raramente, campo abierto.', 'Sustantivo espacial que organiza la geografía hebrea en torno al límite entre interior y exterior. En singular con preposiciones, חוּץ funciona casi como adverbio: ''fuera del campamento'' (Dt 23:13), ''fuera de la ciudad'' (Gn 19:16), definiendo el espacio en relación con cualquier recinto. Pero en plural (חוּצוֹת) se especializa en ''calles'' o ''plazas'' dentro de una población, los espacios públicos donde transcurre la vida: niños jugando (Zac 8:5), mercaderes comerciando, duelo derramándose al aire libre (2 S 1:20). El español sigue fielmente esta división, usando ''afuera/fuera'' para el exterior genérico y ''calles'' para el plural urbano. Proverbios personifica a la Sabiduría clamando ''en las calles'' (בַּחוּצוֹת, Pr 1:20), transformando este humilde término espacial en escenario de revelación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2354', 'spa', 'Hur — nombre propio llevado por el compañero de Moisés, un ancestro judahita de Bezaleel, y otros.', 'El nombre Hur (חוּר, posiblemente con el significado de ''blanco'' o ''noble'') pertenece a varias figuras, la más memorable siendo el hombre que, junto con Aarón, sostuvo las manos cansadas de Moisés durante la batalla contra Amalec en Refidim (Éxodo 17:10, 12) y fue dejado a cargo cuando Moisés subió al Sinaí (Éxodo 24:14). Un judahita llamado Hur fue el abuelo de Bezaleel, el maestro artesano del tabernáculo (Éxodo 31:2; 35:30; 38:22; 1 Crónicas 2:19-20). Otros portadores incluyen un rey madianita muerto por Israel (Números 31:8; Josué 13:21) y un líder postexílico que reparó el muro de Jerusalén (Nehemías 3:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2356', 'spa', 'Agujero, abertura o cavidad — en un muro, una puerta, la tapa de un cofre, o como cueva o escondite.', 'Sustantivo masculino que designa cualquier tipo de agujero o abertura, ya sea natural o hecha por manos humanas. Su campo de aplicación es notablemente diverso: un agujero perforado en un cofre de recaudación (2 R 12:9), un orificio en una puerta por el cual se introduce la mano (Cnt 5:4), un boquete en la pared del templo a través del cual Ezequiel observa idolatría secreta (Ez 8:7), cuevas donde los israelitas se escondieron de los filisteos (1 S 14:11), e incluso las cuencas de los ojos consumidas por la plaga (Zac 14:12). Ya sea en contextos arquitectónicos, anatómicos o geológicos, la palabra denota consistentemente una cavidad o abertura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2361', 'spa', 'Juram/Hiram -- rey de Tiro aliado de David y Salomón; también el maestro artesano tirio', 'Juram (חוּרָם), también escrito Hiram (חִירָם), es un nombre propio que designa a dos figuras destacadas: el rey fenicio de Tiro que suministró cedro, oro y mano de obra especializada para el palacio de David y el Templo de Salomón (1 Cr 14:1; 2 Cr 2:3, 11-12), y el maestro artesano de ascendencia mixta tirio-israelita a quien el rey Juram envió a Salomón para ejecutar los trabajos en bronce del Templo (2 Cr 2:13; 4:11, 16). Las variantes ortográficas Hiram y Juram reflejan diferencias dialectales en la transmisión del hebreo, no individuos distintos. Las doce apariciones del nombre se concentran en el relato de Crónicas sobre la construcción del Templo salomónico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2363a', 'spa', 'Apresurarse, darse prisa; moverse con urgencia (Qal intransitivo); hacer apresurarse, acelerar (Hifil causativo). Verbo de velocidad urgente presente ', 'Apresurarse, darse prisa; moverse con urgencia (Qal intransitivo); hacer apresurarse, acelerar (Hifil causativo). Verbo de velocidad urgente presente en poesía, profecía y narrativa. En el Qal describe la prisa personal: el salmista declara ''me apresuré y no me demoré en guardar tus mandamientos'' (Sal 119:60), y al muchacho de Samuel se le dice que se apresure (1 Sam 20:38). El nombre profético Maher-Shalal-Hash-Baz (Is 8:1, 3) incorpora esta raíz para señalar que el despojo llega velozmente. En el Hifil el significado cambia a aceleración causativa: ''que apresure su obra'' (Is 5:19), y la promesa de Isaías 60:22 de que Dios ''lo acelerará a su tiempo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2365', 'spa', 'Husai — nombre propio del consejero de confianza de David, ''el arquita'', que frustró la revuelta de Absalón.', 'Un nombre propio que identifica a Husai el arquita, uno de los consejeros más leales de David, designado como su ''amigo'' (רֵעֶה דָוִד). Durante la rebelión de Absalón, David envió a Husai de regreso a Jerusalén para contrarrestar el consejo de Ahitofel — una estratagema que resultó decisiva cuando Husai persuadió a Absalón de demorar su persecución, dándole a David tiempo para escapar al otro lado del Jordán (2 Samuel 15:32-17:16). Su hijo Baana sirvió después como uno de los gobernadores de distrito de Salomón (1 Reyes 4:16). El francés y el alemán transliteran el nombre como ''Huschai'', mientras que el español lo rinde como ''Husai''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2367', 'spa', 'Jusam; nombre propio de un rey edomita procedente de la tierra de los temanitas.', 'Nombre propio de un antiguo rey de Edom que sucedió a Jobab y reinó desde la tierra de los temanitas. Aparece tanto en la lista de reyes de Génesis 36 como en su paralelo en 1 Crónicas 1. El nombre podría derivar de una raíz que sugiere premura o anhelo. Las tradiciones en español, francés y alemán conservan formas cercanas al hebreo חוּשָׁם, lo que refleja un reconocimiento uniforme de este gobernante edomita a lo largo de la historia textual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2368', 'spa', 'Un sello o anillo de sellar usado para autenticar documentos, marcar propiedad y como figura de valor precioso.', 'Designa tanto la piedra de sello física como el anillo de sellar que se llevaba en la mano o se colgaba de un cordón alrededor del cuello. Judá entrega su sello con cordón a Tamar como garantía (Génesis 38:18), Jezabel estampa la sentencia de muerte de Nabot con el sello de Acab (1 Reyes 21:8), y las vestiduras sacerdotales están grabadas ''como grabados de sello'' (Éxodo 28:11, 21, 36). En el discurso profético, Hageo compara a Zorobabel con el anillo de sellar de Dios (Hageo 2:23), y Cantares 8:6 suplica: ''Ponme como sello sobre tu corazón.'' El español distingue ''sello'' del ''anillo de sellar'', mientras que el alemán usa ''Siegel''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2370', 'spa', 'Ver o contemplar, especialmente visiones y sueños; el verbo arameo para la percepción profética en Daniel y Esdras', 'Ver o contemplar, especialmente visiones y sueños; el verbo arameo para la percepción profética en Daniel y Esdras');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H2371', 'spa', 'Hazael; nombre propio del rey arameo de Damasco que oprimió a Israel a mediados del siglo IX a.C.', 'Hazael; nombre propio del rey arameo de Damasco que oprimió a Israel a mediados del siglo IX a.C.');